(window.KOTOBA_HK=window.KOTOBA_HK||{})[28]={"n":28,"S":[{"id":"l28a","ti":[[["くらげ","くらげ"],["に","に"],["骨","ほね"],["が","が"],["ない","ない"],["わけ","わけ"]]],"tt":{"az":"Meduzanın niyə sümüyü yoxdur","en":"Why the Jellyfish Has No Bones","ru":"Почему у медузы нет костей"},"P":[{"t":[[["むかしむかし","むかしむかし"],["、"],["海","うみ"],["の","の"],["底","そこ"],["に","に"],["、"],["りっぱな","りっぱな","りっぱ",1],["竜","りゅう"],["の","の"],["王さま","おうさま"],["が","が"]],[["住んでいました","すんでいました","住む",31],["。"],["王さま","おうさま"],["の","の"]],[["お城","おしろ"],["に","に"],["は","は"],["、"],["大きな","おおきな"],["門","もん"],["が","が"]],[["あり","あり","ある",10],["、"],["きれいな","きれいな","きれい",1],["貝","かい"],["が","が"]],[["たくさん","たくさん"]],[["飾ってありました","かざってありました","飾ってありました",36],["。"],["ある日","あるひ"],["、"],["王さま","おうさま"],["の","の"]],[["お妃さま","おひさま"],["が","が"]],[["病気","びょうき"],["に","に"]],[["なってしまいました","なってしまいました","なる",14],["。"]]],"tr":{"az":"Biri var idi, biri yox idi, dənizin dibində əzəmətli bir əjdaha hökmdarı yaşayırdı. Onun sarayının böyük darvazası vardı və hər tərəf gözəl balıqqulaqları ilə bəzədilmişdi. Bir gün hökmdarın arvadı xəstələndi.","en":"Long ago, a magnificent Dragon King lived at the bottom of the sea. His castle had a large gate and was decorated with many beautiful seashells. One day, the queen became ill.","ru":"Давным-давно на дне моря жил величественный Король драконов. У его дворца были большие ворота, а повсюду красовались красивые ракушки. Однажды королева заболела."}},{"t":[[["王さま","おうさま"],["は","は"]],[["海","うみ"],["の","の"],["医者","いしゃ"],["を","を"]],[["呼んでおきました","よんでおきました","呼ぶ",70],["。"],["医者","いしゃ"],["は","は"]],[["お妃さま","おひさま"],["を","を"]],[["よく","よく"]],[["見て","みて","見る",3],["から","から"],["、"],["「"],["猿","さる"],["の","の"],["肝","きも"],["が","が"]],[["必要","ひつよう"],["です","です"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["王さま","おうさま"],["は","は"]],[["困ってしまいました","こまってしまいました","困る",14],["。"],["海","うみ"],["に","に"],["は","は"]],[["猿","さる"],["が","が"]],[["いなかった","いなかった","いる",22],["から","から"],["です","です"],["。"]]],"tr":{"az":"Hökmdar əvvəlcədən dəniz həkimini çağırtdı. Həkim kraliçanı diqqətlə müayinə etdikdən sonra dedi: «Meymunun qaraciyəri lazımdır». Hökmdar çox çətin vəziyyətdə qaldı. Çünki dənizdə meymun yox idi.","en":"The king had called for the sea doctor. After examining the queen carefully, the doctor said, “We need a monkey's liver.” The king was troubled because there were no monkeys in the sea.","ru":"Король заранее вызвал морского врача. Врач внимательно осмотрел королеву и сказал: «Нужна печень обезьяны». Король растерялся, ведь в море не было обезьян."}},{"t":[[["そこ","そこ"],["で","で"],["、"],["王さま","おうさま"],["は","は"]],[["くらげ","くらげ"],["を","を"]],[["呼びました","よびました","呼ぶ",2],["。"],["その","その"],["ころ","ころ"],["の","の"]],[["くらげ","くらげ"],["に","に"],["は","は"],["、"],["強い","つよい"],["骨","ほね"],["と","と"]],[["四本","よんぽん"],["の","の"],["足","あし"],["が","が"]],[["ありました","ありました","ある",2],["。"],["王さま","おうさま"],["は","は"],["「"],["陸","りく"],["へ","へ"]],[["行って","いって","行く",3],["、"],["猿","さる"],["を","を"]],[["連れてきてください","つれてきてください","連れてきてください",71],["」"],["と","と"]],[["頼みました","たのみました","頼む",2],["。"],["くらげ","くらげ"],["は","は"]],[["元気","げんき"],["よく","よく","よい"]],[["出かけました","でかけました","出かける",2],["。"]]],"tr":{"az":"Buna görə hökmdar meduzanı çağırdı. O vaxtlar meduzanın möhkəm sümükləri və dörd ayağı vardı. Hökmdar ondan xahiş etdi: «Quruya get və bir meymun gətir». Meduza həvəslə yola düşdü.","en":"So the king summoned a jellyfish. In those days, jellyfish had strong bones and four legs. The king asked, “Please go to the land and bring back a monkey.” The jellyfish set off cheerfully.","ru":"Тогда король позвал медузу. В те времена у медуз были крепкие кости и четыре ноги. Король попросил: «Отправляйся на сушу и приведи обезьяну». Медуза бодро отправилась в путь."}},{"t":[[["くらげ","くらげ"],["は","は"]],[["海","うみ"],["から","から"]],[["出て","でて","出る",3],["、"],["森","もり"],["へ","へ"]],[["行きました","いきました","行く",2],["。"],["木","き"],["の","の"],["上","うえ"],["に","に"]],[["猿","さる"],["が","が"]],[["一匹","いっぴき"]],[["座っていました","すわっていました","座る",15],["。"],["くらげ","くらげ"],["は","は"],["「"],["海","うみ"],["の","の"],["王さま","おうさま"],["の","の"]],[["お城","おしろ"],["へ","へ"]],[["遊び","あそび","遊ぶ",10],["に","に"]],[["来ません","きません","来る",6],["か","か"],["」"],["と","と"]],[["聞いてみました","きいてみました","聞く",72],["。"],["猿","さる"],["は","は"]],[["おもしろ","おもしろ","おもしろい"],["そう","そう"],["だ","だ","です"],["と","と"]],[["思い","おもい","思う",10],["、"],["何","なん"],["も","も"]],[["持たないで","もたないで","持つ",18],["、"],["くらげ","くらげ"],["と","と"]],[["一緒","いっしょ"],["に","に"]],[["海","うみ"],["へ","へ"]],[["向かいました","むかいました","向かう",2],["。"]]],"tr":{"az":"Meduza dənizdən çıxıb meşəyə getdi. Bir ağacın üstündə meymun oturmuşdu. Meduza ondan soruşdu: «Dəniz hökmdarının sarayına qonaq gəlmək istəməzsən?» Meymun bunun maraqlı olacağını düşünüb özü ilə heç nə götürmədən meduza ilə birlikdə dənizə tərəf yollandı.","en":"The jellyfish left the sea and went into the forest. A monkey was sitting in a tree. The jellyfish tried asking, “Would you like to visit the Sea King's castle?” Thinking it sounded interesting, the monkey headed toward the sea with the jellyfish, bringing nothing along.","ru":"Медуза вышла из моря и отправилась в лес. На дереве сидела обезьяна. Медуза спросила: «Не хочешь побывать в гостях во дворце Морского короля?» Обезьяне это показалось интересным, и она отправилась к морю вместе с медузой, ничего с собой не взяв."}},{"t":[[["海","うみ"],["へ","へ"]],[["入る","はいる","入る",5],["前","まえ"],["に","に"],["、"],["くらげ","くらげ"],["は","は"]],[["大切な","たいせつな","大切",1],["秘密","ひみつ"],["を","を"]],[["話してしまいました","はなしてしまいました","話す",14],["。"],["「"],["王さま","おうさま"],["は","は"]],[["あなた","あなた"],["の","の"],["肝","きも"],["を","を"]],[["欲しがっています","ほしがっています","欲しい",24],["」"],["と","と"]],[["言った","いった","言う",0],["の","の"],["です","です"],["。"],["猿","さる"],["は","は"]],[["びっくり","びっくり"],["しました","しました","する",2],["が","が"],["、"],["すぐ","すぐ"],["に","に"]],[["考えました","かんがえました","考える",2],["。"],["そして","そして"],["「"],["肝","きも"],["は","は"]],[["木","き"],["に","に"]],[["置いた","おいた","置く",0],["まま","まま"],["です","です"],["。"],["取ってきます","とってきます","取る",73],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Dənizə girməzdən əvvəl meduza vacib sirri ağzından qaçırdı. O dedi: «Hökmdar sənin qaraciyərini istəyir». Meymun çox təəccübləndi, amma dərhal bir çıxış yolu düşündü. Sonra dedi: «Qaraciyərimi ağacda qoymuşam. Gedib gətirim».","en":"Before entering the sea, the jellyfish accidentally revealed an important secret. “The king wants your liver,” it said. The monkey was shocked but quickly thought of a plan. “I left my liver in the tree. I'll go and get it,” he said.","ru":"Перед тем как войти в море, медуза случайно раскрыла важную тайну. «Король хочет получить твою печень», – сказала она. Обезьяна испугалась, но быстро придумала план. «Я оставила печень на дереве. Сейчас принесу», – сказала она."}},{"t":[[["くらげ","くらげ"],["は","は"]],[["その","その"],["話","はなし"],["を","を"]],[["信じてしまいました","しんじてしまいました","信じてしまいました",14],["。"],["猿","さる"],["を","を"]],[["森","もり"],["へ","へ"]],[["戻し","もどし","戻し",10],["、"],["自分","じぶん"],["は","は"]],[["海","うみ"],["の","の"],["近く","ちかく"],["で","で"]],[["待っていました","まっていました","待つ",15],["。"],["でも","でも"],["、"],["猿","さる"],["は","は"]],[["木","き"],["に","に"]],[["登った","のぼった","登った",0],["まま","まま"],["、"],["下りてきませんでした","おりてきませんでした","下りてきませんでした",74],["。"],["「"],["肝","きも"],["を","を"]],[["木","き"],["に","に"]],[["置く","おく","置く",5]],[["猿","さる"],["なんて","なんて"]],[["いません","いません","いる",6],["よ","よ"],["」"],["と","と"]],[["笑いました","わらいました","笑う",2],["。"]]],"tr":{"az":"Meduza bu sözlərə inandı. Meymunu meşəyə qaytardı və özü dənizin kənarında gözlədi. Amma meymun ağaca çıxıb orada qaldı, bir daha aşağı enmədi. O gülərək dedi: «Hansı meymun qaraciyərini ağacda qoyar ki?»","en":"The jellyfish believed the story. It took the monkey back to the forest and waited near the sea. But the monkey stayed up in the tree and never came down. “No monkey leaves its liver in a tree!” he laughed.","ru":"Медуза поверила этой истории. Она отвела обезьяну обратно в лес и стала ждать у моря. Но обезьяна забралась на дерево и так и не спустилась. «Разве обезьяны оставляют свою печень на деревьях?» – засмеялась она."}},{"t":[[["くらげ","くらげ"],["は","は"]],[["猿","さる"],["を","を"]],[["連れないで","つれないで","連れないで",18],["、"],["お城","おしろ"],["へ","へ"]],[["帰りました","かえりました","帰る",2],["。"],["王さま","おうさま"],["は","は"]],[["話","はなし"],["を","を"]],[["聞いて","きいて","聞く",3],["、"],["とても","とても"]],[["怒りました","おこりました","怒る",2],["。"],["家来たち","けらいたち"],["は","は"]],[["くらげ","くらげ"],["の","の"],["骨","ほね"],["を","を"]],[["全部","ぜんぶ"]],[["取ってしまいました","とってしまいました","取る",14],["。"],["骨","ほね"],["が","が"]],[["なくなり","なくなり","なくなり",10],["、"],["くらげ","くらげ"],["の","の"],["体","からだ"],["は","は"]],[["やわらかく","やわらかく"]],[["なりました","なりました","なる",2],["。"]]],"tr":{"az":"Meduza meymunu gətirmədən saraya qayıtdı. Hökmdar əhvalatı eşidəndə çox qəzəbləndi. Sarayın xidmətçiləri meduzanın bütün sümüklərini çıxardılar. Sümükləri yox oldu və bədəni yumşaldı.","en":"The jellyfish returned to the castle without the monkey. When the king heard what had happened, he became furious. His servants removed all the jellyfish's bones. Without its bones, the jellyfish's body became soft.","ru":"Медуза вернулась во дворец без обезьяны. Услышав её рассказ, король сильно разгневался. Слуги вынули из медузы все кости. Без костей её тело стало мягким."}},{"t":[[["それから","それから"],["、"],["くらげ","くらげ"],["は","は"]],[["足","あし"],["で","で"]],[["歩けなく","あるけなく","歩けなく",19]],[["なってしまいました","なってしまいました","なる",14],["。"],["今","いま"],["でも","でも"],["、"],["骨","ほね"],["の","の"],["ない","ない"]],[["やわらかい","やわらかい"],["体","からだ"],["の","の"],["まま","まま"],["、"],["海","うみ"],["を","を"]],[["ゆっくり","ゆっくり"]],[["泳いでいます","およいでいます","泳ぐ",33],["。"],["ときどき","ときどき"],["、"],["海","うみ"],["の","の"],["上","うえ"],["を","を"]],[["見て","みて","見る",3],["、"],["「"],["あの","あの"],["猿","さる"],["は","は"]],[["元気","げんき"],["か","か"],["な","な"],["」"],["と","と"]],[["思います","おもいます","思う",11],["。"],["でも","でも"],["、"],["もう","もう"]],[["秘密","ひみつ"],["は","は"]],[["話さない","はなさない","話す",19]],[["つもり","つもり"],["です","です"],["。"]]],"tr":{"az":"O gündən sonra meduza ayaqları ilə yeriyə bilmədi. İndi də sümüksüz, yumşaq bədəni ilə dənizdə asta-asta üzür. Bəzən suyun üzünə baxıb düşünür: «Görəsən, o meymun necədir?» Amma bir daha sirr açmamağa qərar verib.","en":"From then on, the jellyfish could no longer walk on legs. Even today, it swims slowly through the sea with its soft, boneless body. Sometimes it looks toward the surface and wonders, “I wonder how that monkey is doing.” But it intends never to reveal another secret.","ru":"С тех пор медуза больше не могла ходить на ногах. И сегодня она медленно плавает в море со своим мягким телом без костей. Иногда она смотрит на поверхность воды и думает: «Интересно, как поживает та обезьяна?» Но теперь она решила больше никогда не выдавать секреты."}}]},{"id":"l28b","ti":[[["忘れ","わすれ","忘れる",10],["ん","ん"],["ぼう","ぼう"],["の","の"],["小さな","ちいさな"],["魔法","まほう"],["使い","つかい"]]],"tt":{"az":"Unutqan balaca sehrbaz","en":"The Forgetful Little Wizard","ru":"Забывчивый маленький волшебник"},"P":[{"t":[[["山","やま"],["の","の"],["上","うえ"],["の","の"]],[["小さな","ちいさな"],["町","まち"],["に","に"],["、"],["ソラ","ソラ"],["と","と"],["いう","いう","いう",5]],[["若い","わかい"],["魔法","まほう"],["使い","つかい"],["が","が"]],[["住んでいました","すんでいました","住む",31],["。"],["ソラ","ソラ"],["は","は"]],[["空","そら"],["を","を"]],[["飛ぶ","とぶ","飛ぶ",5],["こと","こと"],["が","が"]],[["できました","できました","できる",2],["が","が"],["、"],["忘れ物","わすれもの"],["が","が"]],[["とても","とても"]],[["多い","おおい"],["子","こ"],["でした","でした","です",9],["。"],["毎朝","まいあさ"],["、"],["帽子","ぼうし"],["を","を"]],[["かぶった","かぶった","かぶる",0],["まま","まま"]],[["寝てしまったり","ねてしまったり","寝る",75],["、"],["かばん","かばん"],["を","を"]],[["家","いえ"],["に","に"]],[["忘れたり","わすれたり","忘れる",41]],[["しました","しました","する",2],["。"]]],"tr":{"az":"Dağın başındakı kiçik şəhərdə Sora adlı gənc sehrbaz yaşayırdı. Sora uça bilirdi, amma çox unutqan idi. Hər səhər başında papaqla yuxuya getdiyi və ya çantasını evdə unutduğu olurdu.","en":"In a small town on a mountain lived a young wizard named Sora. Sora could fly through the sky, but he was terribly forgetful. He often fell asleep with his hat still on or left his bag at home.","ru":"В маленьком городке на вершине горы жил юный волшебник по имени Сора. Сора умел летать, но был ужасно забывчивым. Он часто засыпал прямо в шляпе или забывал сумку дома."}},{"t":[[["ある日","あるひ"],["、"],["町","まち"],["で","で"]],[["星","ほし"],["の","の"],["お祭り","おまつり"],["が","が"]],[["ありました","ありました","ある",2],["。"],["ソラ","ソラ"],["は","は"]],[["夜","よる"],["の","の"],["空","そら"],["に","に"]],[["百個","ひゃくこ"],["の","の"],["光","ひかり"],["を","を"]],[["出す","だす","出す",5],["予定","よてい"],["でした","でした","です",9],["。"],["忘れない","わすれない","忘れる",19],["ように","ように","よう",8],["、"],["魔法","まほう"],["の","の"],["本","ほん"],["を","を"]],[["机","つくえ"],["の","の"],["上","うえ"],["に","に"]],[["置いておきました","おいておきました","置く",76],["。"],["大切な","たいせつな","大切",1],["魔法","まほう"],["の","の"],["言葉","ことば"],["も","も"]],[["紙","かみ"],["に","に"]],[["書いてありました","かいてありました","書く",36],["。"]]],"tr":{"az":"Bir gün şəhərdə ulduz festivalı keçirilirdi. Sora gecə səmasında yüz işıq yaratmalı idi. Unutmamaq üçün sehr kitabını qabaqcadan masanın üstünə qoydu. Vacib sehrli sözləri də bir kağıza yazıb hazır saxlamışdı.","en":"One day, the town held a Star Festival. Sora was scheduled to create a hundred lights in the night sky. So he placed his spellbook on his desk to keep from forgetting it. The important magic words were also written on a piece of paper.","ru":"Однажды в городе проходил Фестиваль звёзд. Сора должен был создать в ночном небе сто огоньков. Чтобы ничего не забыть, он заранее положил книгу заклинаний на стол. Важные волшебные слова тоже были записаны на листке бумаги."}},{"t":[[["ところ","ところ"],["が","が"],["、"],["お祭り","おまつり"],["の","の"],["時間","じかん"],["に","に"]],[["なって","なって","なる",3],["、"],["ソラ","ソラ"],["は","は"]],[["本","ほん"],["を","を"]],[["持たないで","もたないで","持つ",18]],[["家","いえ"],["を","を"]],[["出てしまいました","でてしまいました","出る",14],["。"],["広場","ひろば"],["に","に"]],[["着く","つく","着く",5],["と","と"],["、"],["かばん","かばん"],["を","を"]],[["開けてみました","あけてみました","開ける",72],["。"],["しかし","しかし"],["、"],["中","なか"],["に","に"],["は","は"]],[["パン","パン"],["と","と"]],[["古い","ふるい"],["くつ","くつ"],["しか","しか"]],[["ありませんでした","ありませんでした","ある",4],["。"],["「"],["あっ","あっ"],["、"],["本","ほん"],["を","を"]],[["忘れてしまった","わすれてしまった","忘れる",69],["！"],["」"],["と","と"]],[["叫びました","さけびました","叫ぶ",2],["。"]]],"tr":{"az":"Amma festival vaxtı çatanda Sora kitabını götürmədən evdən çıxdı. Meydana çatanda çantasını açıb baxdı. İçəridə isə yalnız çörək və köhnə bir ayaqqabı vardı. «Ay aman, kitabımı unutmuşam!» deyə qışqırdı.","en":"But when it was time for the festival, Sora left home without his book. When he reached the square, he opened his bag to check. Inside were only some bread and an old shoe. “Oh no! I forgot my book!” he cried.","ru":"Но когда пришло время фестиваля, Сора вышел из дома без книги. Добравшись до площади, он открыл сумку и заглянул внутрь. Там лежали только хлеб и старый ботинок. «Ой, я забыл книгу!» – закричал он."}},{"t":[[["ソラ","ソラ"],["は","は"]],[["あわてて","あわてて","あわてて",3]],[["魔法","まほう"],["を","を"]],[["使ってみました","つかってみました","使う",72],["。"],["する","する","する",5],["と","と"],["、"],["空","そら"],["の","の"],["光","ひかり"],["で","で"],["は","は"],["なく","なく","ない"],["、"],["大きな","おおきな"],["緑","みどり"],["の","の"],["かえる","かえる"],["が","が"]],[["現れました","あらわれました","現れる",2],["。"],["かえる","かえる"],["は","は"]],[["飛び上がり","とびあがり","飛び上がり",10],["、"],["町長","ちょうちょう"],["の","の"],["帽子","ぼうし"],["を","を"]],[["取ってしまいました","とってしまいました","取る",14],["。"],["町長","ちょうちょう"],["は","は"]],[["帽子","ぼうし"],["を","を"]],[["取られた","とられた","取る",55],["まま","まま"],["、"],["びっくり","びっくり"],["して","して","する",3]],[["立っていました","たっていました","立つ",15],["。"]]],"tr":{"az":"Sora tələsik sehr etməyə çalışdı. Ancaq göydə işıqlar əvəzinə böyük yaşıl qurbağa peyda oldu. Qurbağa hoppanıb şəhər başçısının papağını götürdü. Şəhər başçısı papağı əlindən alınmış halda heyrətlə dayanıb qaldı.","en":"Sora hurriedly tried using his magic. But instead of lights in the sky, a huge green frog appeared. The frog jumped up and snatched the mayor's hat. The mayor stood there in astonishment, his hat still missing.","ru":"Сора поспешно попробовал применить магию. Но вместо огоньков в небе появилась огромная зелёная лягушка. Она подпрыгнула и утащила шляпу мэра. Мэр стоял в полном изумлении, оставшись без шляпы."}},{"t":[[["その","その"],["とき","とき"],["、"],["ソラ","ソラ"],["の","の"],["友達","ともだち"],["の","の"]],[["ミナ","ミナ"],["が","が"]],[["来ました","きました","来る",2],["。"],["ミナ","ミナ"],["は","は"],["「"],["魔法","まほう"],["の","の"],["本","ほん"],["なら","なら"],["、"],["家","いえ"],["に","に"]],[["置いてあります","おいてあります","置く",77],["よ","よ"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["ソラ","ソラ"],["は","は"]],[["帰ろう","かえろう","帰る",7],["と","と"]],[["しました","しました","する",2],["が","が"],["、"],["ほうき","ほうき"],["が","が"]],[["動きませんでした","うごきませんでした","動く",4],["。"],["急いでいた","いそいでいた","急ぐ",78],["の","の"],["で","で"],["、"],["ほうき","ほうき"],["の","の"],["ひも","ひも"],["を","を"]],[["外さない","はずさない","外さない",19],["まま","まま"]],[["来てしまった","きてしまった","来る",69],["の","の"],["です","です"],["。"]]],"tr":{"az":"Elə bu vaxt Soranın dostu Mina gəldi. Mina dedi: «Sehr kitabın evdə, qoyduğun yerdədir». Sora geri qayıtmaq istədi, amma süpürgəsi tərpənmədi. Tələsdiyindən süpürgənin bağını açmadan gəlmişdi.","en":"Just then, Sora's friend Mina arrived. “Your spellbook is still at home where you left it,” she said. Sora tried to go back, but his broom would not move. In his hurry, he had forgotten to untie the rope around it.","ru":"В этот момент пришла подруга Соры, Мина. «Твоя книга заклинаний лежит дома, там, где ты её оставил», – сказала она. Сора попытался вернуться, но метла не двигалась. В спешке он забыл развязать верёвку, которой она была привязана."}},{"t":[[["ミナ","ミナ"],["は","は"]],[["笑わないで","わらわないで","笑う",18],["、"],["ひも","ひも"],["を","を"]],[["外してくれました","はずしてくれました","外してくれました",54],["。"],["二人","ふたり"],["は","は"]],[["ほうき","ほうき"],["に","に"]],[["乗り","のり"],["、"],["ソラ","ソラ"],["の","の"],["家","いえ"],["へ","へ"]],[["飛びました","とびました","飛ぶ",2],["。"],["本","ほん"],["は","は"]],[["机","つくえ"],["の","の"],["上","うえ"],["に","に"]],[["置いてありました","おいてありました","置く",36],["が","が"],["、"],["窓","まど"],["が","が"]],[["開いた","ひらいた","開く",0],["まま","まま"],["に","に"]],[["なっていました","なっていました","なる",15],["。"],["風","かぜ"],["で","で"]],[["紙","かみ"],["が","が"]],[["飛んでしまい","とんでしまい","飛ぶ",79],["、"],["魔法","まほう"],["の","の"],["言葉","ことば"],["が","が"]],[["わからなく","わからなく","わかる",19]],[["なりました","なりました","なる",2],["。"]]],"tr":{"az":"Mina gülmədən onun süpürgəsinin bağını açdı. İkisi süpürgəyə minib Soranın evinə uçdu. Kitab masanın üstündə idi, amma pəncərə açıq qalmışdı. Külək kağızı uçurmuşdu və sehrli sözləri oxumaq artıq mümkün deyildi.","en":"Without laughing, Mina untied the rope for him. The two climbed onto the broom and flew to Sora's house. The book was on the desk, but the window had been left open. The wind had blown away the paper, so they could no longer find the magic words.","ru":"Мина не стала смеяться и отвязала верёвку. Они вдвоём сели на метлу и полетели к дому Соры. Книга лежала на столе, но окно осталось открытым. Ветер унёс листок, и теперь они не могли найти волшебные слова."}},{"t":[[["ソラ","ソラ"],["は","は"]],[["泣きそうに","なきそうに","泣く",12]],[["なりました","なりました","なる",2],["。"],["でも","でも"],["、"],["ミナ","ミナ"],["は","は"],["「"],["本","ほん"],["を","を"]],[["見ないで","みないで","見る",18],["、"],["自分","じぶん"],["で","で"]],[["考えてみましょう","かんがえてみましょう","考える",80],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["ソラ","ソラ"],["は","は"]],[["目","め"],["を","を"]],[["閉じて","とじて","閉じる",3],["、"],["みんな","みんな"],["の","の"],["笑顔","えがお"],["を","を"]],[["思い出しました","おもいだしました","思い出す",2],["。"],["そして","そして"],["、"],["小さな","ちいさな"],["光","ひかり"],["の","の"],["魔法","まほう"],["を","を"]],[["使ってみました","つかってみました","使う",72],["。"],["する","する","する",5],["と","と"],["、"],["空","そら"],["に","に"]],[["一つ","ひとつ"],["の","の"],["金色","きんいろ"],["の","の"],["星","ほし"],["が","が"]],[["光りました","ひかりました","光る",2],["。"]]],"tr":{"az":"Sora az qala ağlayacaqdı. Amma Mina dedi: «Kitaba baxmadan özümüz bir şey fikirləşək». Sora gözlərini yumub hamının gülümsəyən üzünü xatırladı. Sonra kiçik bir işıq sehri etməyə çalışdı. Birdən göydə qızılı bir ulduz parladı.","en":"Sora almost began to cry. But Mina said, “Let's try thinking for ourselves without looking at the book.” Sora closed his eyes and remembered everyone's smiling faces. Then he tried a small light spell. A single golden star appeared in the sky.","ru":"Сора чуть не заплакал. Но Мина сказала: «Давай попробуем придумать что-нибудь сами, не заглядывая в книгу». Сора закрыл глаза и вспомнил улыбки всех жителей. Затем он попробовал простое заклинание света. И в небе засияла одна золотая звезда."}},{"t":[[["その","その"],["星","ほし"],["から","から"]],[["百個","ひゃくこ"],["の","の"],["小さな","ちいさな"],["光","ひかり"],["が","が"]],[["生まれ","うまれ","生まれ",10],["、"],["町中","まちなか"],["が","が"]],[["明るく","あかるく","明るい"]],[["なりました","なりました","なる",2],["。"],["大きな","おおきな"],["かえる","かえる"],["も","も"]],[["星","ほし"],["を","を"]],[["見て","みて","見る",3],["、"],["うれし","うれし","うれしい"],["そうに","そうに","そう",8]],[["鳴きました","なきました","鳴く",2],["。"],["次","つぎ"],["の","の"],["日","ひ"],["、"],["ソラ","ソラ"],["は","は"]],[["忘れ物","わすれもの"],["を","を"]],[["しない","しない","する",19],["ように","ように","よう",8],["、"],["かばん","かばん"],["に","に"]],[["大きな","おおきな"],["紙","かみ"],["を","を"]],[["はっておきました","はっておきました","はっておきました",76],["。"],["でも","でも"],["、"],["その","その"],["紙","かみ"],["に","に"],["は","は"],["「"],["かばん","かばん"],["を","を"]],[["忘れない","わすれない","忘れる",19],["！"],["」"],["と","と"]],[["書いてありました","かいてありました","書く",36],["。"]]],"tr":{"az":"Həmin ulduzdan yüz kiçik işıq yarandı və bütün şəhər işıqlandı. Nəhəng qurbağa da ulduza baxıb sevinclə quruldadı. Ertəsi gün Sora bir daha əşyalarını unutmamaq üçün çantasına böyük kağız yapışdırdı. Amma kağızda belə yazılmışdı: «Çantanı unutma!»","en":"A hundred little lights sprang from that star, illuminating the whole town. Even the giant frog looked up and croaked happily. The next day, Sora stuck a large note on his bag so he would not forget anything. But the note said, “Don't forget your bag!”","ru":"От этой звезды появились сто маленьких огоньков, и весь город озарился светом. Даже огромная лягушка посмотрела на звезду и радостно заквакала. На следующий день Сора приклеил к сумке большую записку, чтобы больше ничего не забывать. Но на записке было написано: «Не забудь сумку!»"}}]},{"id":"l28c","ti":[[["消えた","きえた","消える",0],["青い","あおい"],["傘","かさ"]]],"tt":{"az":"Yoxa çıxan mavi çətir","en":"The Disappearing Blue Umbrella","ru":"Исчезнувший синий зонт"},"P":[{"t":[[["小さな","ちいさな"],["町","まち"],["に","に"],["、"],["ハナ","ハナ"],["と","と"],["いう","いう","いう",5]],[["女の子","おんなのこ"],["が","が"]],[["住んでいました","すんでいました","住む",31],["。"],["ハナ","ハナ"],["は","は"]],[["毎朝","まいあさ"],["、"],["駅","えき"],["の","の"],["近く","ちかく"],["の","の"]],[["パン屋","パンや"],["で","で"]],[["パン","パン"],["を","を"]],[["買いました","かいました","買う",2],["。"],["ある","ある","ある(連体詞)"],["朝","あさ"],["、"],["空","そら"],["が","が"]],[["暗く","くらく","暗い"]],[["なりました","なりました","なる",2],["。"],["お母さん","おかあさん"],["は","は"],["「"],["雨","あめ"],["が","が"]],[["降る","ふる","降る",5],["から","から"],["、"],["傘","かさ"],["を","を"]],[["持っていき","もっていき","持つ",81],["なさい","なさい","なさる",10],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Kiçik bir şəhərdə Hana adlı qız yaşayırdı. Hana hər səhər stansiyanın yaxınlığındakı çörək dükanından çörək alırdı. Bir səhər hava qaraldı. Anası dedi: «Yağış yağacaq, çətirini götür».","en":"A girl named Hana lived in a small town. Every morning, she bought bread at a bakery near the station. One morning, the sky grew dark. Her mother said, “It's going to rain, so take your umbrella.”","ru":"В маленьком городке жила девочка по имени Хана. Каждое утро она покупала хлеб в пекарне возле станции. Однажды утром небо потемнело. Мама сказала: «Скоро пойдёт дождь, возьми зонт»."}},{"t":[[["ハナ","ハナ"],["は","は"]],[["青い","あおい"],["傘","かさ"],["を","を"]],[["持って","もって","持つ",3]],[["出かけました","でかけました","出かける",2],["。"],["パン屋","パンや"],["の","の"],["入り口","いりぐち"],["に","に"],["は","は"],["、"],["傘","かさ"],["を","を"]],[["入れる","いれる","入れる",5],["箱","はこ"],["が","が"]],[["置いてありました","おいてありました","置く",36],["。"],["ハナ","ハナ"],["は","は"]],[["傘","かさ"],["を","を"]],[["箱","はこ"],["に","に"]],[["入れておきました","いれておきました","入れる",76],["。"],["店","みせ"],["の","の"],["中","なか"],["で","で"],["は","は"],["、"],["あまい","あまい"],["パン","パン"],["の","の"],["いい","いい"],["におい","におい"],["が","が"]],[["していました","していました","する",15],["。"]]],"tr":{"az":"Hana mavi çətirini götürüb evdən çıxdı. Çörək dükanının girişində çətirlər üçün qutu qoyulmuşdu. Hana çətirini ora yerləşdirdi. Dükanın içindən şirin çörəklərin xoş ətri gəlirdi.","en":"Hana took her blue umbrella and went out. A box for umbrellas had been placed by the bakery entrance. Hana put her umbrella inside. The shop was filled with the lovely smell of sweet bread.","ru":"Хана взяла синий зонт и вышла из дома. У входа в пекарню стояла коробка для зонтов. Хана положила туда свой зонт. Внутри магазина приятно пахло сладкими булочками."}},{"t":[[["パン","パン"],["を","を"]],[["買って","かって","買う",3]],[["外","そと"],["へ","へ"]],[["出る","でる","出る",5],["と","と"],["、"],["雨","あめ"],["が","が"]],[["降っていました","ふっていました","降る",15],["。"],["ハナ","ハナ"],["は","は"]],[["箱","はこ"],["を","を"]],[["見てみました","みてみました","見る",72],["が","が"],["、"],["青い","あおい"],["傘","かさ"],["が","が"]],[["ありませんでした","ありませんでした","ある",4],["。"],["「"],["だれ","だれ"],["か","か"],["が","が"]],[["持っていってしまった","もっていってしまった","持つ",82],["の","の"],["か","か"],["な","な"],["」"],["と","と"]],[["思いました","おもいました","思う",2],["。"],["ハナ","ハナ"],["は","は"]],[["パン","パン"],["の","の"],["袋","ふくろ"],["を","を"]],[["頭","あたま"],["に","に"]],[["のせた","のせた","のせる",0],["まま","まま"],["、"],["家","いえ"],["へ","へ"]],[["走りました","はしりました","走る",2],["。"]]],"tr":{"az":"Çörəyi alıb bayıra çıxanda yağış yağırdı. Hana qutuya baxdı, amma mavi çətiri yox idi. «Görəsən, kimsə götürüb aparıb?» deyə düşündü. Çörək paketini başının üstünə tutaraq evə qaçdı.","en":"When Hana came outside with her bread, it was raining. She looked in the box, but her blue umbrella was gone. “I wonder if someone took it,” she thought. Holding the bag of bread over her head, she ran home.","ru":"Когда Хана вышла из пекарни с хлебом, шёл дождь. Она заглянула в коробку, но синего зонта там не было. «Неужели кто-то забрал его?» – подумала она. Прикрыв голову пакетом с хлебом, Хана побежала домой."}},{"t":[[["家","いえ"],["に","に"]],[["着く","つく","着く",5],["と","と"],["、"],["服","ふく"],["も","も"]],[["くつ","くつ"],["も","も"]],[["ぬれていました","ぬれていました","ぬれる",15],["。"],["お母さん","おかあさん"],["は","は"]],[["窓","まど"],["を","を"]],[["閉めて","しめて","閉める",3],["から","から"],["、"],["ハナ","ハナ"],["に","に"]],[["タオル","タオル"],["を","を"]],[["渡しました","わたしました","渡す",2],["。"],["ハナ","ハナ"],["は","は"],["「"],["傘","かさ"],["を","を"]],[["なくしてしまった","なくしてしまった","なくしてしまった",69],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["お母さん","おかあさん"],["は","は"]],[["怒らないで","おこらないで","怒る",18],["、"],["「"],["明日","あした"],["、"],["もう","もう"],["一度","いちど"]],[["探してみましょう","さがしてみましょう","探してみましょう",80],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Evə çatanda Hananın həm paltarı, həm də ayaqqabıları islanmışdı. Anası pəncərəni bağlayıb ona dəsmal verdi. Hana dedi: «Çətirimi itirmişəm». Anası hirslənmədən cavab verdi: «Sabah bir də axtararıq».","en":"By the time Hana reached home, her clothes and shoes were soaked. Her mother closed the window and handed her a towel. “I've lost my umbrella,” Hana said. Instead of getting angry, her mother replied, “Let's look for it again tomorrow.”","ru":"Когда Хана добралась домой, её одежда и обувь промокли. Мама закрыла окно и дала ей полотенце. «Я потеряла зонт», – сказала Хана. Мама не рассердилась и ответила: «Давай завтра ещё раз поищем»."}},{"t":[[["次","つぎ"],["の","の"],["朝","あさ"],["、"],["ハナ","ハナ"],["は","は"]],[["パン","パン"],["を","を"]],[["買わないで","かわないで","買う",18],["、"],["まっすぐ","まっすぐ"]],[["パン屋","パンや"],["へ","へ"]],[["行きました","いきました","行く",2],["。"],["店","みせ"],["の","の"],["前","まえ"],["に","に"],["は","は"],["「"],["忘れ物","わすれもの"],["は","は"]],[["店","みせ"],["の","の"],["中","なか"],["に","に"]],[["あります","あります","ある",11],["」"],["と","と"]],[["書いてありました","かいてありました","書く",36],["。"],["ハナ","ハナ"],["は","は"]],[["中","なか"],["へ","へ"]],[["入り","はいり","入る",10],["、"],["店","みせ"],["の","の"],["おばあさん","おばあさん"],["に","に"]],[["聞いてみました","きいてみました","聞く",72],["。"],["おばあさん","おばあさん"],["は","は"]],[["にこにこ","にこにこ"],["して","して","する",3],["、"],["小さな","ちいさな"],["部屋","へや"],["へ","へ"]],[["案内","あんない"],["しました","しました","する",2],["。"]]],"tr":{"az":"Ertəsi səhər Hana çörək almaq əvəzinə birbaşa çörək dükanına getdi. Dükanın qabağında «Unudulan əşyalar içəridədir» yazılmışdı. Hana içəri girib yaşlı satıcı qadından soruşdu. Qadın gülümsəyərək onu kiçik otağa apardı.","en":"The next morning, Hana went straight to the bakery without buying bread. A sign outside said, “Lost items are kept inside.” Hana entered and asked the elderly shopkeeper about her umbrella. Smiling, the woman led her into a small room.","ru":"На следующее утро Хана пошла прямо в пекарню, не покупая хлеб. У входа висела табличка: «Забытые вещи находятся внутри». Хана вошла и спросила пожилую хозяйку о зонте. Улыбаясь, женщина проводила её в маленькую комнату."}},{"t":[[["部屋","へや"],["に","に"],["は","は"]],[["青い","あおい"],["傘","かさ"],["が","が"]],[["五本","ごぽん"],["も","も"]],[["並べてありました","ならべてありました","並べてありました",36],["。"],["ハナ","ハナ"],["は","は"]],[["一本","いっぽん"],["ずつ","ずつ"]],[["開けてみました","あけてみました","開ける",72],["が","が"],["、"],["どれ","どれ"],["も","も"]],[["自分","じぶん"],["の","の"],["傘","かさ"],["で","で"],["は","は"]],[["ありませんでした","ありませんでした","ある",4],["。"],["する","する","する",5],["と","と"],["、"],["部屋","へや"],["の","の"],["すみ","すみ"],["から","から"],["「"],["ニャー","ニャー"],["」"],["と","と"]],[["声","こえ"],["が","が"]],[["聞こえました","きこえました","聞こえる",2],["。"],["そこ","そこ"],["に","に"],["は","は"]],[["猫","ねこ"],["が","が"]],[["青い","あおい"],["布","ぬの"],["の","の"],["下","した"],["で","で"]],[["寝ていました","ねていました","寝る",15],["。"]]],"tr":{"az":"Otaqda beş mavi çətir yan-yana düzülmüşdü. Hana onları bir-bir açıb yoxladı, amma heç biri onun deyildi. Birdən otağın küncündən «Miyau» səsi gəldi. Orada bir pişik mavi parçanın altında yatırdı.","en":"Five blue umbrellas were lined up in the room. Hana opened them one by one, but none was hers. Then she heard a “Meow” from a corner of the room. A cat was sleeping under a piece of blue cloth.","ru":"В комнате стояли пять синих зонтов. Хана раскрыла их один за другим, но ни один не был её зонтом. Вдруг из угла раздалось «Мяу». Там под синей тканью спала кошка."}},{"t":[[["よく","よく"]],[["見る","みる","見る",5],["と","と"],["、"],["その","その"],["青い","あおい"],["布","ぬの"],["は","は"]],[["ハナ","ハナ"],["の","の"],["傘","かさ"],["でした","でした","です",9],["。"],["傘","かさ"],["は","は"]],[["開いた","ひらいた","開く",0],["まま","まま"],["、"],["猫","ねこ"],["の","の"],["小さな","ちいさな"],["家","いえ"],["に","に"]],[["なっていました","なっていました","なる",15],["。"],["おばあさん","おばあさん"],["は","は"],["「"],["昨日","きのう"],["、"],["雨","あめ"],["に","に"]],[["ぬれた","ぬれた","ぬれる",0],["子猫","こねこ"],["が","が"]],[["来た","きた","来る",0],["の","の"],["で","で"],["、"],["傘","かさ"],["を","を"]],[["開いておいた","ひらいておいた","開く",83],["ん","ん"],["です","です"],["」"],["と","と"]],[["説明","せつめい"],["しました","しました","する",2],["。"],["ハナ","ハナ"],["は","は"]],[["子猫","こねこ"],["を","を"]],[["起こさないで","おこさないで","起こさないで",18],["、"],["そっと","そっと"]],[["なでました","なでました","なでる",2],["。"]]],"tr":{"az":"Diqqətlə baxanda məlum oldu ki, həmin mavi parça Hananın çətiri idi. Çətir açıq qalmış və pişik üçün balaca evə çevrilmişdi. Yaşlı qadın izah etdi: «Dünən yağışda islanmış bir pişik balası gəldi, mən də onun üçün çətiri açıq qoydum». Hana pişiyi oyatmadan yavaşca sığalladı.","en":"Looking closely, Hana realized that the blue cloth was her umbrella. It had been left open and had become a tiny home for the cat. The shopkeeper explained, “A wet kitten came in yesterday, so I opened the umbrella and left it out for her.” Without waking the kitten, Hana gently stroked her.","ru":"Присмотревшись, Хана поняла, что синяя ткань была её зонтом. Он стоял раскрытым и превратился в маленький домик для кошки. Хозяйка объяснила: «Вчера пришёл промокший котёнок, и я раскрыла для него зонт». Хана осторожно погладила котёнка, не разбудив его."}},{"t":[[["ハナ","ハナ"],["は","は"]],[["傘","かさ"],["を","を"]],[["持って","もって","持つ",3],["帰らないで","かえらないで","帰る",18],["、"],["もう","もう"],["一","いち"],["日","にち"]],[["貸す","かす","貸す",5],["こと","こと"],["に","に"]],[["しました","しました","する",2],["。"],["次","つぎ"],["の","の"],["日","ひ"],["、"],["子猫","こねこ"],["は","は"]],[["ハナ","ハナ"],["の","の"],["家","いえ"],["に","に"]],[["来る","きたる","来る",5],["こと","こと"],["に","に"]],[["なりました","なりました","なる",2],["。"],["お母さん","おかあさん"],["は","は"]],[["猫","ねこ"],["の","の"],["ため","ため"],["に","に"]],[["小さな","ちいさな"],["ベッド","ベッド"],["を","を"]],[["用意","ようい"],["しておきました","しておきました","する",76],["。"],["それから","それから"]],[["ハナ","ハナ"],["は","は"],["、"],["晴れた","はれた","晴れた",0],["日","ひ"],["でも","でも"]],[["ときどき","ときどき"]],[["傘","かさ"],["を","を"]],[["開いてみました","ひらいてみました","開く",72],["。"],["する","する","する",5],["と","と"],["、"],["子猫","こねこ"],["は","は"]],[["必ず","かならず"]],[["その","その"],["下","した"],["に","に"]],[["入って","はいって","入る",3],["、"],["うれし","うれし","うれしい"],["そうに","そうに","そう",8]],[["寝てしまいました","ねてしまいました","寝る",14],["。"]]],"tr":{"az":"Hana çətiri evə aparmayıb bir gün də pişiyə verməyə qərar verdi. Ertəsi gün pişik balasının Hananın evinə köçməsi qərara alındı. Anası pişik üçün qabaqcadan balaca yataq hazırladı. O vaxtdan Hana günəşli havalarda da bəzən çətiri açırdı. Belə olan kimi pişik mütləq altına girib xoşbəxt halda yuxuya gedirdi.","en":"Hana decided not to take the umbrella home and to lend it for one more day. The next day, arrangements were made for the kitten to come and live at Hana's house. Her mother prepared a little bed for the kitten. From then on, Hana sometimes opened her umbrella even on sunny days. Whenever she did, the kitten crawled underneath and happily fell asleep.","ru":"Хана решила не забирать зонт домой, а одолжить его ещё на один день. На следующий день было решено, что котёнок переедет к Хане. Мама заранее приготовила ему маленькую кроватку. С тех пор Хана иногда раскрывала зонт даже в солнечную погоду. И каждый раз котёнок забирался под него и счастливо засыпал."}}]}],"G":{"あっ":{"b":"あっ","p":"in","m":{"az":"Ah!; A!","en":"Ah!; Oh!","ru":"Ах!; Ой!"},"n":{"az":"Qəfil təəccüb və ya fərqinə varmanı bildirir.","en":"Expresses sudden surprise or realization.","ru":"Выражает внезапное удивление или осознание."}},"あなた":{"b":"あなた","p":"pr","m":{"az":"sən, siz","en":"you","ru":"ты, вы"},"n":{"az":"Yaponcada adamı adı ilə çağırmaq daha nəzakətlidir (ケンさん). あなた bəzən soyuq səslənir.","en":"Calling people by name (ケンさん) is more polite; あなた can sound cold.","ru":"Вежливее обращаться по имени (ケンさん); あなた может звучать холодно."}},"あの":{"b":"あの","p":"dm","m":{"az":"o (uzaqdakı)","en":"that (over there)","ru":"тот (вдали)"},"n":{"az":"İsimdən əvvəl gəlir: あの人 = o adam, あの星 = o ulduz. Danışandan da, dinləyəndən də uzaq olan şey.","en":"Comes before a noun: あの人 = that person, あの星 = that star. Something far from both speakers.","ru":"Ставится перед существительным: あの人 = тот человек. Далеко от обоих собеседников."}},"ある":{"b":"ある","p":"v","m":{"az":"olmaq, var olmaq (cansız şeylər)","en":"to be, to exist (things)","ru":"быть, иметься (о предметах)"},"n":{"az":"Cansız şeylər üçün: 電池がありました = batareya var idi. Canlılar üçün いる. 書いてありました = yazılmışdı (yazılı vəziyyətdə idi).","en":"For non-living things: 電池がありました = there was a battery. For living things use いる. 書いてありました = was written (and stayed so).","ru":"Для неодушевлённых: 電池がありました = была батарейка. Для живых – いる. 書いてありました = было написано."}},"ある(連体詞)":{"b":"ある","p":"dm","m":{"az":"bir, hansısa (bir)","en":"a certain, one","ru":"некий, один"},"n":{"az":"ある朝 = bir səhər; ある日 = bir gün. İsimdən əvvəl gələndə 'var olmaq' feili deyil.","en":"ある朝 = one morning. Before a noun it is not the verb 'to exist'.","ru":"ある朝 = однажды утром. Перед существительным это не глагол 'быть'."}},"ある日":{"b":"ある日 (あるひ)","p":"ex","m":{"az":"bir gün","en":"one day","ru":"однажды"}},"いい":{"b":"いい・良い (よい)","p":"ai","m":{"az":"yaxşı","en":"good","ru":"хороший"},"n":{"az":"İ-sifətdir, lakin dəyişən formaları よい əsasından yaranır: よくない, よかった.","en":"An i-adjective whose inflected forms use よい: よくない, よかった.","ru":"И-прилагательное, изменяемые формы которого образуются от よい: よくない, よかった."}},"いう":{"b":"という","p":"ex","m":{"az":"adlı, deyilən","en":"called, named","ru":"под названием"},"n":{"az":"N という名前 = N adlı ad: 「かぐや」という名前 = «Kaquya» adı.","en":"N という名前 = the name \"N\".","ru":"N という名前 = имя «N»."}},"いる":{"b":"いる","p":"v","m":{"az":"olmaq, var olmaq (canlılar); yaşamaq","en":"to be, exist (living things)","ru":"быть, находиться (о живых)"},"n":{"az":"Canlılar üçün: 女の子がいました = bir qız var idi. 〜ている = davam edən hal.","en":"For living things: 女の子がいました = there was a girl. 〜ている = continuous.","ru":"Для живых: 女の子がいました = была девочка. 〜ている – длительный вид."}},"うれしい":{"b":"嬉しい (うれしい)","p":"ai","m":{"az":"sevincli, şad","en":"happy, glad","ru":"радостный, довольный"},"n":{"az":"い sifətidir, うれし bağlayıcı və ya başqa forma yaratmaq üçün əsasdır.","en":"An i-adjective, with うれし as the stem used to form other expressions.","ru":"Прилагательное на い, うれし - основа для образования других форм."}},"おばあさん":{"b":"おばあさん","p":"n","m":{"az":"nənə; qarı","en":"grandmother; old woman","ru":"бабушка; старушка"}},"おもしろい":{"b":"おもしろい","p":"ai","m":{"az":"maraqlı, əyləncəli","en":"interesting, amusing","ru":"интересный, забавный"},"n":{"az":"い-sifətdir və həm maraqlı, həm də gülməli mənasında işlənə bilər.","en":"An i-adjective that can mean either interesting or amusing.","ru":"Прилагательное на い, которое может означать интересный или забавный."}},"お城":{"b":"城 (しろ)","p":"n","m":{"az":"qala, qəsr","en":"castle","ru":"замок"}},"お母さん":{"b":"お母さん (おかあさん)","p":"n","m":{"az":"ana","en":"mother; mom","ru":"мама; мать"},"n":{"az":"Anaya müraciətdə və başqasının anası haqqında işlənir; kənar şəxslərə öz anandan danışarkən adətən 母 deyilir.","en":"Used to address your mother or refer to someone else's; use 母 for your own mother when speaking to outsiders.","ru":"Используется при обращении к маме или о чужой матери; о своей матери посторонним обычно говорят 母."}},"お祭り":{"b":"お祭り (おまつり)","p":"n","m":{"az":"bayram; festival","en":"festival; celebration","ru":"праздник; фестиваль"},"n":{"az":"お nəzakət bildirən ön şəkilçidir; 祭り də işlənir.","en":"お is a polite prefix; 祭り is also used.","ru":"お является вежливой приставкой; также употребляется 祭り."}},"か":{"b":"か","p":"pt","m":{"az":"sual hissəciyi","en":"question particle","ru":"вопросительная частица"},"n":{"az":"Cümlənin sonuna gəlir və onu suala çevirir: 学生ですか = Tələbəsən? Yaponcada sual işarəsi əvəzinə adətən 。 yazılır.","en":"Goes at the end and turns the sentence into a question: 学生ですか = Are you a student? Japanese usually writes 。 instead of ?.","ru":"Ставится в конце и делает предложение вопросом: 学生ですか = Вы студент? Обычно пишут 。, а не ?."}},"かえる":{"b":"蛙 (かえる)","p":"n","m":{"az":"qurbağa","en":"frog","ru":"лягушка"},"n":{"az":"Eyni oxunuşlu 帰る evə qayıtmaq deməkdir.","en":"The homophone 帰る means to return home.","ru":"Омоним 帰る означает возвращаться домой."}},"かばん":{"b":"鞄 (かばん)","p":"n","m":{"az":"çanta","en":"bag","ru":"сумка"}},"かぶる":{"b":"被る (かぶる)","p":"v","m":{"az":"başa taxmaq; örtmək","en":"to wear on the head; to cover","ru":"надевать на голову; покрывать"},"n":{"az":"帽子をかぶる papaq taxmaq, かぶっています isə taxmış vəziyyətdə olmaq deməkdir.","en":"帽子をかぶる means to put on a hat, while かぶっています describes wearing it.","ru":"帽子をかぶる означает надеть шляпу, а かぶっています - быть в шляпе."}},"から":{"b":"から","p":"pt","m":{"az":"-dan, -dən (haradan)","en":"from","ru":"из, от"},"n":{"az":"Başlanğıc nöqtəsini göstərir: 月から来ました = Aydan gəldim.","en":"Marks the starting point: 月から来ました = I came from the Moon.","ru":"Указывает исходную точку: 月から来ました = Я прилетела с Луны."}},"が":{"b":"が","p":"pt","m":{"az":"subyekt hissəciyi","en":"subject marker","ru":"частица подлежащего"},"n":{"az":"Hərəkəti edən və ya mövcud olan şeyi göstərir: 先生が来ました = müəllim gəldi. Yeni məlumatı vurğulayır; は isə artıq bəlli mövzunu.","en":"Marks who does the action or what exists: 先生が来ました = a teacher came. Introduces new information, while は marks a known topic.","ru":"Отмечает деятеля или то, что существует: 先生が来ました = пришёл учитель. Вводит новую информацию; は – уже известную тему."}},"きれい":{"b":"きれい","p":"an","m":{"az":"gözəl, təmiz","en":"beautiful, clean","ru":"красивый, чистый"},"n":{"az":"な-sifətdir: きれいな花 = gözəl çiçək; い ilə bitsə də い-sifət deyil.","en":"A na-adjective despite ending in い: きれいな花 = beautiful flower.","ru":"Это な-прилагательное, несмотря на окончание い: きれいな花 = красивый цветок."}},"こと":{"b":"こと","p":"n","m":{"az":"iş; hadisə; məsələ","en":"thing; matter; event","ru":"дело; событие; обстоятельство"},"n":{"az":"Felə qoşularaq hərəkəti isimləşdirir: 読むこと oxumaq hərəkəti.","en":"It nominalizes verbs: 読むこと means the act of reading.","ru":"Превращает глагол в существительное: 読むこと означает чтение."}},"しか":{"b":"しか","p":"pt","m":{"az":"yalnız, ancaq","en":"only, nothing but","ru":"только, лишь"},"n":{"az":"Həmişə inkarla işlənir: 一つしかありません = cəmi bir dənə var.","en":"Used with a negative predicate: 一つしかありません = there is only one.","ru":"Употребляется с отрицанием: 一つしかありません = есть только одна штука."}},"すぐ":{"b":"すぐ","p":"ad","m":{"az":"tez, dərhal","en":"soon, immediately","ru":"сразу, скоро"},"n":{"az":"すぐに = dərhal.","en":"すぐに = right away.","ru":"すぐに = сразу."}},"する":{"b":"する","p":"v","m":{"az":"etmək; (səs, iy) gəlmək","en":"to do; (a sound) to be heard","ru":"делать; (о звуке) слышаться"},"n":{"az":"Ən çox işlənən feil. 音がしました = səs gəldi. 〜ようとしました = ...-mağa çalışdı.","en":"Most common verb. 音がしました = there was a sound. 〜ようとしました = tried to ...","ru":"Самый частый глагол. 音がしました = раздался звук. 〜ようとしました = попытался ..."}},"ずつ":{"b":"ずつ","p":"pt","m":{"az":"...-ar, hərəsi bir","en":"each, apiece","ru":"по (одному)"},"n":{"az":"一つずつ = hərəsi bir dənə.","en":"一つずつ = one each.","ru":"一つずつ = по одному."}},"そう":{"b":"そう","p":"ad","m":{"az":"elə; belə","en":"so; that way","ru":"так"},"n":{"az":"そうです təsdiq, そうします isə deyilən şəkildə hərəkət etməyi bildirir.","en":"そうです confirms something; そうします means to do it that way.","ru":"そうです выражает подтверждение, а そうします означает сделать именно так."}},"そこ":{"b":"そこ","p":"pr","m":{"az":"ora","en":"there","ru":"там"},"n":{"az":"Dinləyiciyə yaxın və ya söhbətdə artıq qeyd olunan yeri göstərir.","en":"Refers to a place near the listener or already mentioned.","ru":"Обозначает место рядом с собеседником или уже упомянутое место."}},"そして":{"b":"そして","p":"cj","m":{"az":"və, sonra","en":"and, then","ru":"и, затем"}},"そっと":{"b":"そっと","p":"ad","m":{"az":"ehmalca, yavaşca","en":"gently, softly","ru":"осторожно, тихонько"}},"その":{"b":"その","p":"dm","m":{"az":"o (bəhs edilən)","en":"that (the one mentioned)","ru":"тот, этот (упомянутый)"},"n":{"az":"その時 = o vaxt, elə bu an.","en":"その時 = at that moment.","ru":"その時 = в тот момент."}},"それから":{"b":"それから","p":"cj","m":{"az":"sonra, ondan sonra","en":"then, after that","ru":"потом, затем"}},"たくさん":{"b":"たくさん","p":"ad","m":{"az":"çox; çoxlu","en":"many; much; a lot","ru":"много"},"n":{"az":"İsimlə たくさんの本, fellə isə たくさん食べる şəklində işlənir.","en":"Use たくさんの本 with a noun and たくさん食べる with a verb.","ru":"С существительным употребляется たくさんの本, с глаголом たくさん食べる."}},"だれ":{"b":"だれ","p":"pr","m":{"az":"kim","en":"who","ru":"кто"},"n":{"az":"Sual sözü: あの人はだれですか = O adam kimdir? Daha nəzakətli forması どなた.","en":"Question word: あの人はだれですか = Who is that person? More polite: どなた.","ru":"Вопросительное слово: あの人はだれですか = Кто этот человек? Вежливее: どなた."}},"で":{"b":"で","p":"pt","m":{"az":"-da/-də (hərəkətin yeri); ilə (vasitə)","en":"at, in (place of action); with, by (means)","ru":"в, на (место действия); с помощью"},"n":{"az":"Hərəkətin baş verdiyi yer: 山で竹を切る = dağda bambuk kəsmək; 庭で泣く = bağçada ağlamaq. Vasitə: 両手で = iki əllə. Varlıq üçün に işlənir, hərəkət üçün で.","en":"Place where an action happens: 山で = on the mountain; means: 両手で = with both hands. Existence uses に, actions use で.","ru":"Место действия: 山で = в горах; средство: 両手で = обеими руками. Для существования – に, для действия – で."}},"できる":{"b":"できる","p":"v","m":{"az":"bacarmaq; hazır olmaq","en":"be able to; be ready","ru":"мочь; быть готовым"},"n":{"az":"Bacarığı 日本語ができる, tamamlanmanı isə ご飯ができる kimi ifadə edir.","en":"Expresses ability in 日本語ができる and completion in ご飯ができる.","ru":"Выражает умение в 日本語ができる и готовность в ご飯ができる."}},"です":{"b":"です","p":"cp","m":{"az":"-dır, -dir (nəzakətli)","en":"is, am, are (polite)","ru":"есть, является (вежл.)"},"n":{"az":"İsmin sonunda gəlir: 学生です = Tələbəyəm / tələbədir. İndiki zaman, təsdiq, nəzakətli forma. Şəxs bildirmir: kontekstdən anlaşılır.","en":"Ends a noun sentence: 学生です = I am / he is a student. Present, affirmative, polite. It shows no person: context tells.","ru":"Завершает именное предложение: 学生です = я студент / он студент. Настоящее время, утверждение, вежливо. Лицо не выражает."}},"でも":{"b":"でも","p":"cj","m":{"az":"amma, lakin","en":"but","ru":"но"},"n":{"az":"Cümlənin əvvəlində gəlir və əvvəlki fikrə zidd fikir gətirir.","en":"Starts a sentence and introduces a contrast.","ru":"Начинает предложение и вводит противопоставление."}},"と":{"b":"と","p":"pt","m":{"az":"ilə; (sitat) deyə","en":"and, with; (quote marker)","ru":"и, с; (цитата)"},"n":{"az":"İki mənası var: 1) おじいさんとおばあさん = baba və nənə; 2) sitatdan sonra: 「森です」と言いました = «Moriyəm» dedi. 〜と思う = ...deyə düşünmək. Feildən sonra (開けると) isə 'edəndə, ...-ınca' deməkdir.","en":"Two main uses: 1) 'and' between nouns; 2) after a quote: 「…」と言いました = said \"…\". After a verb (開けると) it means 'when/as soon as'.","ru":"Основные значения: 1) 'и' между существительными; 2) после цитаты: 「…」と言いました = сказал «…». После глагола (開けると) – 'когда/как только'."}},"とき":{"b":"時 (とき)","p":"n","m":{"az":"vaxt, an","en":"time, moment","ru":"время, момент"}},"とても":{"b":"とても","p":"ad","m":{"az":"çox","en":"very","ru":"очень"}},"どれ":{"b":"どれ","p":"pr","m":{"az":"hansı, hansısı","en":"which one","ru":"который, какой из них"},"n":{"az":"Bir neçə şeydən seçim üçündür; isimdən əvvəl どの işlənir.","en":"Used to choose among items; use どの before a noun.","ru":"Используется для выбора; перед существительным ставится どの."}},"ない":{"b":"無い (ない)","p":"ai","m":{"az":"yoxdur; mövcud deyil","en":"not exist; not have","ru":"нет; отсутствует"},"n":{"az":"İ-sifət kimi dəyişir: なく və なかった; felə qoşulduqda inkar da bildirir.","en":"Inflects like an i-adjective: なく and なかった; attached to a verb, it also marks negation.","ru":"Изменяется как и-прилагательное: なく и なかった; при глаголе также выражает отрицание."}},"なさる":{"b":"なさる","p":"v","m":{"az":"etmək (hörmətli forma)","en":"to do (honorific)","ru":"делать (уважительная форма)"},"n":{"az":"する felinin hörmətli formasıdır; なさい əmr və göstərişlərdə işlənir.","en":"Honorific form of する; なさい is used for instructions and commands.","ru":"Уважительная форма する; なさい используется в указаниях и приказах."}},"なでる":{"b":"撫でる (なでる)","p":"v","m":{"az":"sığallamaq","en":"to stroke; to pet","ru":"гладить; ласкать"}},"なる":{"b":"なる","p":"v","m":{"az":"olmaq, çevrilmək","en":"to become","ru":"становиться"},"n":{"az":"N/na-sifət + に なる; i-sifət: い → く なる (大きくなる = böyümək).","en":"N/na-adj + に なる; i-adj: い → く なる (大きくなる = grow big).","ru":"N/na-прил. + に なる; i-прил.: い → く なる (大きくなる = вырасти)."}},"に":{"b":"に","p":"pt","m":{"az":"-a/-ə; -da/-də; -ı (hədəf)","en":"to; at, in; (target)","ru":"в, на; к (цель)"},"n":{"az":"Çoxmənalı hissəcik: yer (教室の前に立つ = sinifin qabağında dayanmaq), istiqamət/hədəf (大学に来る = universitetə gəlmək), zaman (二年前に = iki il əvvəl), nəticə (静かになる). Mənanı feil müəyyən edir.","en":"Many uses: location of existence/position, destination or target, a point in time, the result of a change. The verb decides which.","ru":"Многозначная частица: место (стоять перед), направление/цель (прийти в университет), время (два года назад), результат изменения. Значение задаёт глагол."}},"にこにこ":{"b":"にこにこ","p":"ad","m":{"az":"gülümsəyərək","en":"with a cheerful smile","ru":"с улыбкой"},"n":{"az":"にこにこする = gülümsəmək, adətən səssiz və şən şəkildə.","en":"にこにこする means to smile cheerfully, usually without laughing aloud.","ru":"にこにこする означает приветливо улыбаться, обычно без громкого смеха."}},"ぬれる":{"b":"濡れる (ぬれる)","p":"v","m":{"az":"islanmaq","en":"get wet","ru":"намокать"},"n":{"az":"Təsirsiz feldir; təsirli qarşılığı 濡らす islatmaq deməkdir.","en":"An intransitive verb; its transitive counterpart 濡らす means to wet something.","ru":"Непереходный глагол; переходная пара 濡らす означает намочить."}},"の":{"b":"の","p":"pt","m":{"az":"-ın, -in (yiyəlik); iki ismi bağlayır","en":"of, -'s; links two nouns","ru":"связывает два существительных (род. падеж)"},"n":{"az":"N1 の N2: N1 N2-ni təyin edir. さくら大学の学生 = Sakura Universitetinin tələbəsi; ロボットの先生 = robot müəllim (növ bildirir).","en":"N1 の N2: N1 describes N2. さくら大学の学生 = a student of Sakura University; ロボットの先生 = a robot teacher (kind).","ru":"N1 の N2: N1 определяет N2. さくら大学の学生 = студент университета Сакура; ロボットの先生 = учитель-робот (вид)."}},"のせる":{"b":"乗せる (のせる)","p":"v","m":{"az":"qoymaq (üstünə)","en":"to put on","ru":"класть на"}},"は":{"b":"は (wa)","p":"pt","m":{"az":"mövzu hissəciyi","en":"topic marker","ru":"частица темы"},"n":{"az":"Cümlənin nədən bəhs etdiyini göstərir. Yazılışı は, amma hissəcik kimi 'wa' oxunur: わたしは = 'mənə gəlincə / mən'.","en":"Marks what the sentence is about. Written は but read 'wa' as a particle: わたしは = 'as for me'.","ru":"Отмечает, о чём предложение. Пишется は, но как частица читается 'wa': わたしは = 'что касается меня'."}},"びっくり":{"b":"びっくり","p":"ad","m":{"az":"təəccüb; diksinmə","en":"surprise; startlement","ru":"удивление; испуг"},"n":{"az":"びっくりする təəccüblənmək və ya qəfil diksinmək deməkdir.","en":"びっくりする means to be surprised or startled.","ru":"びっくりする означает удивиться или вздрогнуть от неожиданности."}},"へ":{"b":"へ (e)","p":"pt","m":{"az":"-a/-ə (istiqamət)","en":"to, toward","ru":"к, в (направление)"},"n":{"az":"İstiqamət bildirir: 家へ帰る = evə qayıtmaq. Hissəcik kimi 'e' oxunur.","en":"Shows direction: 家へ帰る = go home. Read 'e' as a particle.","ru":"Направление: 家へ帰る = вернуться домой. Как частица читается 'e'."}},"ほうき":{"b":"箒 (ほうき)","p":"n","m":{"az":"süpürgə","en":"broom","ru":"метла, веник"}},"まま":{"b":"まま","p":"n","m":{"az":"olduğu kimi, ...-mış halda","en":"as it is","ru":"как есть"},"n":{"az":"入ったまま = içində qalaraq.","en":"入ったまま = while staying inside.","ru":"入ったまま = оставаясь внутри."}},"みんな":{"b":"みんな","p":"n","m":{"az":"hamı, hamısı","en":"everyone, all","ru":"все"}},"むかしむかし":{"b":"昔々 (むかしむかし)","p":"ex","m":{"az":"biri var idi, biri yox idi","en":"once upon a time","ru":"давным-давно"},"n":{"az":"Yapon nağıllarının ənənəvi başlanğıcı.","en":"The traditional opening of Japanese tales.","ru":"Традиционное начало японских сказок."}},"も":{"b":"も","p":"pt","m":{"az":"də, da (həmçinin)","en":"also, too","ru":"тоже, также"},"n":{"az":"は-nin yerinə gəlir: ケンさんも = 'Ken də'. は ilə birlikdə işlənmir.","en":"Replaces は: ケンさんも = 'Ken too'. Not used together with は.","ru":"Ставится вместо は: ケンさんも = 'Кен тоже'. Вместе с は не используется."}},"もう":{"b":"もう","p":"ad","m":{"az":"daha; artıq","en":"more; already","ru":"ещё; уже"},"n":{"az":"もう一度 = bir daha.","en":"もう一度 = once more.","ru":"もう一度 = ещё раз."}},"ゆっくり":{"b":"ゆっくり","p":"ad","m":{"az":"yavaş-yavaş, tələsmədən","en":"slowly","ru":"медленно"}},"よ":{"b":"よ","p":"pt","m":{"az":"cümləsonu vurğu ədatı","en":"sentence-final emphasis particle","ru":"конечная усилительная частица"},"n":{"az":"Cümlənin sonunda yeni məlumatı, əminliyi və ya xəbərdarlığı vurğulayır: ここですよ “Buradadır”, 危ないよ “Ehtiyatlı ol”; 行こうよ kimi ifadələrdə çağırışı gücləndirir.","en":"At sentence end, it stresses information, assurance, or warning, as in ここですよ “It's here” and 危ないよ “Watch out,” and strengthens invitations such as 行こうよ “Let's go.”","ru":"В конце предложения подчёркивает сообщение, уверенность или предупреждение: ここですよ «Это здесь», 危ないよ «Осторожно», а также усиливает призыв: 行こうよ «Пойдём»."}},"よい":{"b":"よい","p":"ai","m":{"az":"yaxşı","en":"good","ru":"хороший"},"n":{"az":"い-sifətidir və いい ilə eynimənalıdır; よう bəzi ifadələrdə, məsələn おはよう-da görünən formadır.","en":"An い-adjective equivalent to いい; よう occurs in some expressions such as おはよう.","ru":"い-прилагательное, равнозначное いい; форма よう встречается в выражениях вроде おはよう."}},"よう":{"b":"よう","p":"an","m":{"az":"kimi, sanki","en":"like, as if","ru":"подобно, словно"},"n":{"az":"Bənzətmə bildirir: Nのような isimdən əvvəl, Nのように feldən əvvəl, Nのようです isə cümlənin sonunda işlənir.","en":"Expresses resemblance: Nのような modifies a noun, Nのように modifies a verb, and Nのようです ends a sentence.","ru":"Выражает сходство: Nのような стоит перед существительным, Nのように перед глаголом, а Nのようです завершает предложение."}},"よく":{"b":"よく","p":"ad","m":{"az":"yaxşıca, diqqətlə","en":"well, carefully","ru":"хорошо, внимательно"}},"りっぱ":{"b":"立派 (りっぱ)","p":"an","m":{"az":"möhtəşəm; əla; ləyaqətli","en":"splendid; admirable","ru":"великолепный; достойный"},"n":{"az":"な-sifətdir; isimdən əvvəl 立派な işlənir.","en":"It is a na-adjective; 立派な is used before a noun.","ru":"Это na-прилагательное; перед существительным используется 立派な."}},"わかる":{"b":"分かる (わかる)","p":"v","m":{"az":"başa düşmək; anlamaq","en":"understand","ru":"понимать"},"n":{"az":"Başa düşülən şey adətən が ilə göstərilir: 日本語が分かる.","en":"What is understood usually takes が: 日本語が分かる.","ru":"То, что понимают, обычно оформляется частицей が: 日本語が分かる."}},"を":{"b":"を (o)","p":"pt","m":{"az":"təsirlik hissəcik (-ı, -i)","en":"object marker","ru":"частица прямого объекта"},"n":{"az":"Feilin təsir etdiyi əşyanı göstərir: かばんを持つ = çantanı tutmaq. Yazılışı を, oxunuşu 'o'.","en":"Marks the direct object: かばんを持つ = hold a bag. Written を, read 'o'.","ru":"Отмечает прямое дополнение: かばんを持つ = держать сумку. Пишется を, читается 'o'."}},"ん":{"b":"ん (← の)","p":"pt","m":{"az":"(izah bildirir)","en":"(explanatory)","ru":"(пояснение)"},"n":{"az":"〜んです / 〜のです: səbəb və ya izah verəndə işlənir; danışıqda の → ん.","en":"〜んです / 〜のです adds an explanation; in speech の becomes ん.","ru":"〜んです / 〜のです – объяснение; в речи の → ん."}},"ソラ":{"b":"ソラ","p":"nm","m":{"az":"Sora","en":"Sora","ru":"Сора"}},"タオル":{"b":"タオル","p":"n","m":{"az":"dəsmal","en":"towel","ru":"полотенце"}},"ハナ":{"b":"ハナ","p":"nm","m":{"az":"Hana (qız adı)","en":"Hana (girl's name)","ru":"Хана (женское имя)"}},"パン":{"b":"パン","p":"n","m":{"az":"çörək","en":"bread","ru":"хлеб"}},"パン屋":{"b":"パン屋 (パンや)","p":"n","m":{"az":"çörək dükanı, çörəkçi","en":"bakery, baker","ru":"булочная, пекарь"}},"ベッド":{"b":"ベッド","p":"n","m":{"az":"çarpayı","en":"bed","ru":"кровать"}},"ミナ":{"b":"ミナ","p":"nm","m":{"az":"Mina","en":"Mina","ru":"Мина"}},"一":{"b":"一 (いち)","p":"nu","m":{"az":"bir","en":"one","ru":"один"}},"一つ":{"b":"一つ (ひとつ)","p":"n","m":{"az":"bir (dənə)","en":"one (thing)","ru":"одна (штука)"},"n":{"az":"Ümumi sayğac: 一つ, 二つ, 三つ.","en":"General counter: 一つ, 二つ, 三つ.","ru":"Общий счёт: 一つ, 二つ, 三つ."}},"一匹":{"b":"一匹 (いっぴき)","p":"nu","m":{"az":"bir heyvan, bir ədəd","en":"one small animal","ru":"одно животное"},"n":{"az":"匹 kiçik heyvanlar üçündür, 一匹 いっぴき oxunur.","en":"匹 counts small animals, and 一匹 is pronounced いっぴき.","ru":"Счётный суффикс 匹 для небольших животных, 一匹 читается いっぴき."}},"一度":{"b":"一度 (いちど)","p":"n","m":{"az":"bir dəfə","en":"once","ru":"один раз"}},"一本":{"b":"一本 (いっぽん)","p":"n","m":{"az":"bir dənə (uzun əşya)","en":"one (long thing)","ru":"одна штука (длинная)"},"n":{"az":"本 – uzun, nazik əşyalar üçün sayğac (bambuk, qələm, şüşə).","en":"本 – counter for long, thin things.","ru":"本 – счётный суффикс для длинных предметов."}},"一緒":{"b":"一緒 (いっしょ)","p":"n","m":{"az":"birlik, bir yerdə olma","en":"being together","ru":"совместность, пребывание вместе"},"n":{"az":"一緒に “birlikdə” deməkdir: 友達と一緒に “dostla birlikdə”.","en":"一緒に means “together,” as in 友達と一緒に “together with a friend.”","ru":"一緒に означает «вместе»: 友達と一緒に «вместе с другом»."}},"上":{"b":"上 (うえ)","p":"n","m":{"az":"üst","en":"top, above","ru":"верх, на"},"n":{"az":"N の 上 = N-in üstü.","en":"N の 上 = on top of N.","ru":"N の 上 = на N."}},"下":{"b":"下 (した)","p":"n","m":{"az":"alt, aşağı","en":"below, under","ru":"низ, под"},"n":{"az":"その下に = onun altına.","en":"その下に = under it.","ru":"その下に = под этим."}},"中":{"b":"中 (なか)","p":"n","m":{"az":"iç","en":"inside","ru":"внутри"},"n":{"az":"N の 中 = N-in içi.","en":"N の 中 = inside N.","ru":"N の 中 = внутри N."}},"二人":{"b":"二人 (ふたり)","p":"n","m":{"az":"iki nəfər, ikisi","en":"two people","ru":"двое"},"n":{"az":"İnsan sayğacı: 一人 (ひとり), 二人 (ふたり), 三人 (さんにん).","en":"People counter: 一人, 二人, 三人.","ru":"Счёт людей: 一人, 二人, 三人."}},"五本":{"b":"五本 (ごほん)","p":"nu","m":{"az":"beş uzun əşya","en":"five long objects","ru":"пять длинных предметов"},"n":{"az":"本 qələm və şüşə kimi uzun əşyaları sayır, 五本 ごほん oxunur.","en":"本 counts long objects such as pencils and bottles, and 五本 is pronounced ごほん.","ru":"Счётный суффикс 本 для длинных предметов, например карандашей и бутылок, 五本 читается ごほん."}},"今":{"b":"今 (いま)","p":"n","m":{"az":"indi","en":"now","ru":"сейчас"},"n":{"az":"今も = indi də.","en":"今も = even now.","ru":"今も = и сейчас."}},"住む":{"b":"住む (すむ)","p":"v","m":{"az":"yaşamaq, məskunlaşmaq","en":"to live, to reside","ru":"жить, проживать"},"n":{"az":"住んで て-formadır, 場所に住む müəyyən yerdə yaşamaq deməkdir.","en":"住んで is the te-form, and 場所に住む means to live in a place.","ru":"住んで - форма на て, 場所に住む означает жить в определённом месте."}},"体":{"b":"体 (からだ)","p":"n","m":{"az":"bədən","en":"body","ru":"тело"}},"何":{"b":"何 (なに・なん)","p":"pr","m":{"az":"nə","en":"what","ru":"что"},"n":{"az":"何ですか və 何時 kimi birləşmələrdə なん, 何を kimi hallarda isə なに oxunur.","en":"Read なん in expressions such as 何ですか and 何時, but なに in 何を.","ru":"Читается なん в сочетаниях 何ですか и 何時, но なに в 何を."}},"使う":{"b":"使う (つかう)","p":"v","m":{"az":"istifadə etmək; işlətmək","en":"to use","ru":"использовать; пользоваться"},"n":{"az":"N を使う şəklində işlənir: パソコンを使う.","en":"Takes を for the object: パソコンを使う means to use a computer.","ru":"Используется с を для объекта: パソコンを使う означает пользоваться компьютером."}},"傘":{"b":"傘 (かさ)","p":"n","m":{"az":"çətir","en":"umbrella","ru":"зонт"}},"元気":{"b":"元気 (げんき)","p":"an","m":{"az":"gümrah; sağlam","en":"energetic; well","ru":"бодрый; здоровый"},"n":{"az":"な-sifətidir: 元気な子; 元気です = özünü yaxşı hiss edir.","en":"A な-adjective: 元気な子; 元気です means being well.","ru":"な-прилагательное: 元気な子; 元気です означает хорошее самочувствие."}},"光":{"b":"光 (ひかり)","p":"n","m":{"az":"işıq","en":"light","ru":"свет"}},"光る":{"b":"光る (ひかる)","p":"v","m":{"az":"parlamaq, işıq saçmaq","en":"to shine","ru":"светиться, сиять"},"n":{"az":"光るランプ = parlayan lampa: feil isimdən əvvəl təyin kimi gəlir.","en":"光るランプ = a glowing lamp: a verb before a noun describes it.","ru":"光るランプ = светящаяся лампа: глагол перед сущ. – определение."}},"入り口":{"b":"入り口 (いりぐち)","p":"n","m":{"az":"giriş","en":"entrance","ru":"вход"}},"入る":{"b":"入る (はいる)","p":"v","m":{"az":"girmək","en":"to enter","ru":"входить"},"n":{"az":"入り、 = girib (feilin kökü ilə bağlama).","en":"入り、 = went in and ...","ru":"入り、 = вошла и ..."}},"入れる":{"b":"入れる (いれる)","p":"v","m":{"az":"içəri qoymaq; daxil etmək","en":"to put in; to insert","ru":"класть внутрь; вставлять"},"n":{"az":"Təsirlidir: 箱に入れる; təsirsiz qarşılığı 入る-dur.","en":"Transitive: 箱に入れる; its intransitive partner is 入る.","ru":"Переходный: 箱に入れる; непереходная пара: 入る."}},"全部":{"b":"全部 (ぜんぶ)","p":"n","m":{"az":"hamısı, bütün","en":"all, everything","ru":"всё, целиком"},"n":{"az":"全部で = ümumilikdə; 全部食べました = hamısını yedim.","en":"全部で = in total; 全部食べました = ate everything.","ru":"全部で = всего; 全部食べました = съел всё."}},"出かける":{"b":"出かける (でかける)","p":"v","m":{"az":"evdən çıxmaq; yola düşmək","en":"go out; set off","ru":"выходить; отправляться"}},"出す":{"b":"出す (だす)","p":"v","m":{"az":"çıxarmaq","en":"to take out","ru":"вынимать"}},"出る":{"b":"出る (でる)","p":"v","m":{"az":"çıxmaq","en":"to go out","ru":"выходить"},"n":{"az":"庭に出る = bağçaya çıxmaq.","en":"庭に出る = go out into the garden.","ru":"庭に出る = выйти в сад."}},"前":{"b":"前 (まえ)","p":"n","m":{"az":"qabaq, ön; əvvəl","en":"front; before","ru":"перед; раньше"},"n":{"az":"N の 前 = N-in qabağı. 二年前 = iki il əvvəl.","en":"N の 前 = in front of N. 二年前 = two years ago.","ru":"N の 前 = перед N. 二年前 = два года назад."}},"動く":{"b":"動く (うごく)","p":"v","m":{"az":"hərəkət etmək, işləmək","en":"to move, to operate","ru":"двигаться, работать"},"n":{"az":"I qrup feldir: 動きました = hərəkət etdi; 動かす = hərəkət etdirmək.","en":"A Group 1 verb: 動きました = moved; 動かす = to move something.","ru":"Глагол I группы: 動きました = двигался; 動かす = приводить в движение."}},"医者":{"b":"医者 (いしゃ)","p":"n","m":{"az":"həkim","en":"doctor","ru":"врач"}},"友達":{"b":"友達 (ともだち)","p":"n","m":{"az":"dost","en":"friend","ru":"друг"}},"取る":{"b":"取る (とる)","p":"v","m":{"az":"götürmək, almaq","en":"to take, to pick up","ru":"брать, поднимать"},"n":{"az":"Əşyanı götürmək üçün 取る, şəkil çəkmək üçün eyni oxunuşlu 撮る işlənir.","en":"Use 取る for taking an object and the identically pronounced 撮る for taking a photo.","ru":"Для взятия предмета используется 取る, а для фотографии используется 撮る с тем же чтением."}},"古い":{"b":"古い (ふるい)","p":"ai","m":{"az":"köhnə; qədim","en":"old","ru":"старый; древний"},"n":{"az":"İ-sifətdir; əşya və tikililər üçün işlənir, insanın yaşını bildirmir.","en":"An i-adjective used for things and buildings, not a person's age.","ru":"И-прилагательное для вещей и зданий, не для возраста человека."}},"叫ぶ":{"b":"叫ぶ (さけぶ)","p":"v","m":{"az":"qışqırmaq; hayqırmaq","en":"to shout; to cry out","ru":"кричать; восклицать"}},"向かう":{"b":"向かう (むかう)","p":"v","m":{"az":"istiqamətlənmək; tərəfə getmək","en":"to head toward; to face","ru":"направляться; быть обращённым"},"n":{"az":"場所に向かう bir yerə doğru getmək deməkdir.","en":"場所に向かう means to head toward a place.","ru":"場所に向かう означает направляться к месту."}},"呼ぶ":{"b":"呼ぶ (よぶ)","p":"v","m":{"az":"çağırmaq, adlandırmaq","en":"call, name","ru":"звать, называть"},"n":{"az":"Şəxs を ilə göstərilir; AをBと呼ぶ “A-nı B adlandırmaq” deməkdir.","en":"The person takes を; AをBと呼ぶ means “call A B.”","ru":"Человек обозначается с を; AをBと呼ぶ означает «называть A именем B»."}},"困る":{"b":"困る (こまる)","p":"v","m":{"az":"çətin vəziyyətdə qalmaq; çətinlik çəkmək","en":"be in trouble; be at a loss","ru":"оказаться в затруднении"},"n":{"az":"困っている hazırda çətin vəziyyətdə olmağı bildirir; səbəb に ilə göstərilə bilər.","en":"困っている describes being in difficulty; the cause can be marked by に.","ru":"困っている описывает состояние затруднения; причина может оформляться に."}},"声":{"b":"声 (こえ)","p":"n","m":{"az":"səs (insan, heyvan)","en":"voice","ru":"голос"}},"外":{"b":"外 (そと)","p":"n","m":{"az":"çöl, bayır","en":"outside","ru":"снаружи"},"n":{"az":"N の 外 = N-in çölü: 窓の外 = pəncərənin arxası (çöldə).","en":"N の 外 = outside N.","ru":"N の 外 = снаружи N."}},"多い":{"b":"多い (おおい)","p":"ai","m":{"az":"çox; çoxsaylı","en":"many; numerous","ru":"многочисленный; много"},"n":{"az":"い-sifətdir; 多くて bağlayıcı formadır və adətən 人が多い deyilir.","en":"It is an i-adjective; 多くて is its linking form, and 人が多い is the usual pattern.","ru":"Это i-прилагательное; 多くて - соединительная форма, обычно говорят 人が多い."}},"夜":{"b":"夜 (よる)","p":"n","m":{"az":"gecə","en":"night","ru":"ночь"}},"大きな":{"b":"大きな (おおきな)","p":"dm","m":{"az":"böyük","en":"big","ru":"большой"},"n":{"az":"Yalnız isimdən əvvəl gəlir; 大きい ilə eyni mənadadır.","en":"Only before a noun; same as 大きい.","ru":"Только перед сущ.; то же, что 大きい."}},"大切":{"b":"大切 (たいせつ)","p":"an","m":{"az":"vacib, əziz","en":"important, precious","ru":"важный, дорогой"},"n":{"az":"Na-sifətidir: 大切な物 “əziz əşya”; 大切にする “qayğı ilə yanaşmaq, əziz tutmaq” deməkdir.","en":"A na-adjective: 大切な物 “a precious thing”; 大切にする means “cherish or take good care of.”","ru":"Прилагательное на な: 大切な物 «дорогая вещь»; 大切にする означает «беречь, дорожить»."}},"女の子":{"b":"女の子 (おんなのこ)","p":"n","m":{"az":"qız uşağı","en":"girl","ru":"девочка"}},"子":{"b":"子 (こ)","p":"n","m":{"az":"uşaq; övlad","en":"child","ru":"ребёнок"},"n":{"az":"わたしの子 = mənim övladım.","en":"わたしの子 = my child.","ru":"わたしの子 = мой ребёнок."}},"家":{"b":"家 (いえ)","p":"n","m":{"az":"ev","en":"house, home","ru":"дом"}},"寝る":{"b":"寝る (ねる)","p":"v","m":{"az":"yatmaq; yuxuya getmək","en":"to sleep; to go to bed","ru":"спать; ложиться спать"},"n":{"az":"寝ていました = yatırdı.","en":"寝ていました means was sleeping.","ru":"寝ていました означает «спал»."}},"小さな":{"b":"小さな (ちいさな)","p":"dm","m":{"az":"balaca, kiçik","en":"small, little","ru":"маленький"},"n":{"az":"Yalnız isimdən əvvəl gəlir (小さな音). Mənaca 小さい ilə eynidir.","en":"Only used before a noun; same meaning as 小さい.","ru":"Только перед существительным; то же, что 小さい."}},"山":{"b":"山 (やま)","p":"n","m":{"az":"dağ","en":"mountain","ru":"гора"}},"布":{"b":"布 (ぬの)","p":"n","m":{"az":"parça","en":"cloth, fabric","ru":"ткань"}},"帰る":{"b":"帰る (かえる)","p":"v","m":{"az":"qayıtmaq (evə, öz yerinə)","en":"to return home","ru":"возвращаться"},"n":{"az":"家へ帰るとちゅうで = evə qayıdarkən yolda.","en":"家へ帰るとちゅうで = on the way home.","ru":"家へ帰るとちゅうで = по дороге домой."}},"帽子":{"b":"帽子 (ぼうし)","p":"n","m":{"az":"papaq; şlyapa","en":"hat; cap","ru":"шляпа; шапка"}},"広場":{"b":"広場 (ひろば)","p":"n","m":{"az":"meydan, açıq sahə","en":"square, open space","ru":"площадь, открытое пространство"}},"店":{"b":"店 (みせ)","p":"n","m":{"az":"mağaza; dükan","en":"shop; store","ru":"магазин; лавка"}},"座る":{"b":"座る (すわる)","p":"v","m":{"az":"oturmaq","en":"sit down","ru":"садиться"},"n":{"az":"Oturulan yer に ilə göstərilir: 椅子に座る “stulda oturmaq”.","en":"The seat or sitting place takes に: 椅子に座る “sit on a chair.”","ru":"Место обозначается с に: 椅子に座る «сесть на стул»."}},"強い":{"b":"強い (つよい)","p":"ai","m":{"az":"güclü, qüvvətli","en":"strong, powerful","ru":"сильный"},"n":{"az":"い-sifətdir; əksi 弱い - zəif.","en":"An i-adjective; its opposite is 弱い, weak.","ru":"Это i-прилагательное; антоним 弱い - слабый."}},"待つ":{"b":"待つ (まつ)","p":"v","m":{"az":"gözləmək","en":"wait for","ru":"ждать"},"n":{"az":"Gözlənilən şəxs və ya şey を ilə işlənir; て-forması 待って olur.","en":"The person or thing awaited takes を; the て-form is 待って.","ru":"Тот, кого ждут, или то, чего ждут, обозначается с を; форма на て: 待って."}},"忘れる":{"b":"忘れる (わすれる)","p":"v","m":{"az":"unutmaq","en":"to forget","ru":"забывать"},"n":{"az":"Nを忘れる həm nəyisə unutmaq, həm də bir yerdə qoyub gəlmək mənasında işlənir.","en":"Nを忘れる can mean to forget something or leave it behind.","ru":"Nを忘れる может означать забыть что-либо или оставить это где-либо."}},"怒る":{"b":"怒る (おこる)","p":"v","m":{"az":"hirslənmək; danlamaq","en":"to get angry; to scold","ru":"сердиться; ругать"},"n":{"az":"Hirslənmək üçün 人に怒る, danlamaq üçün 人を怒る işlənir.","en":"人に怒る means to be angry with someone; 人を怒る means to scold someone.","ru":"人に怒る означает сердиться на кого-то, а 人を怒る означает ругать кого-то."}},"思い出す":{"b":"思い出す (おもいだす)","p":"v","m":{"az":"xatırlamaq, yada salmaq","en":"remember, recall","ru":"вспоминать"}},"思う":{"b":"思う (おもう)","p":"v","m":{"az":"düşünmək, fikirləşmək","en":"to think","ru":"думать"},"n":{"az":"〜と思いました = ...deyə düşündü.","en":"〜と思いました = thought that ...","ru":"〜と思いました = подумал, что ..."}},"急ぐ":{"b":"急ぐ (いそぐ)","p":"v","m":{"az":"tələsmək","en":"hurry","ru":"спешить"},"n":{"az":"て forması 急いで olur.","en":"Its て-form is 急いで.","ru":"Форма на て: 急いで."}},"持つ":{"b":"持つ (もつ)","p":"v","m":{"az":"tutmaq, daşımaq; sahib olmaq","en":"to hold, to carry; to have","ru":"держать, нести; иметь"},"n":{"az":"かばんを持って = çantanı tutub (te-forması: hərəkətlər ardıcıllığı).","en":"かばんを持って = holding a bag.","ru":"かばんを持って = держа сумку."}},"日":{"b":"日 (ひ)","p":"n","m":{"az":"gün; günəş","en":"day; sun","ru":"день; солнце"},"n":{"az":"Müstəqil söz kimi çox vaxt ひ oxunur; tarixlərdə və birləşmələrdə oxunuşu dəyişir.","en":"Usually read ひ as a standalone word; its reading changes in dates and compounds.","ru":"Как отдельное слово обычно читается ひ; в датах и сложных словах чтение меняется."}},"明るい":{"b":"明るい (あかるい)","p":"ai","m":{"az":"işıqlı, parlaq","en":"bright","ru":"светлый, яркий"},"n":{"az":"明るく光る = parlaq işıq saçmaq.","en":"明るく光る = shine brightly.","ru":"明るく光る = ярко светиться."}},"明日":{"b":"明日 (あした)","p":"n","m":{"az":"sabah","en":"tomorrow","ru":"завтра"},"n":{"az":"Vaxt bildirəndə adətən に işlənmir: 明日行きます.","en":"Usually takes no に as a time expression: 明日行きます.","ru":"При обозначении времени обычно употребляется без に: 明日行きます."}},"星":{"b":"星 (ほし)","p":"n","m":{"az":"ulduz","en":"star","ru":"звезда"}},"昨日":{"b":"昨日 (きのう)","p":"n","m":{"az":"dünən","en":"yesterday","ru":"вчера"},"n":{"az":"Vaxt bildirəndə adətən に işlənmir: 昨日来ました.","en":"Usually takes no に as a time expression: 昨日来ました.","ru":"При обозначении времени обычно употребляется без に: 昨日来ました."}},"時間":{"b":"時間 (じかん)","p":"n","m":{"az":"vaxt, saat","en":"time, hour","ru":"время, час"},"n":{"az":"食べる時間 = yemək vaxtı (feil isimdən əvvəl).","en":"食べる時間 = the time to eat.","ru":"食べる時間 = время еды."}},"暗い":{"b":"暗い (くらい)","p":"ai","m":{"az":"qaranlıq, tutqun","en":"dark, gloomy","ru":"тёмный, мрачный"},"n":{"az":"İ-sifətidir və həm zəif işığı, həm də tutqun əhvalı bildirə bilər.","en":"An i-adjective that can describe low light or a gloomy mood.","ru":"Прилагательное на い, описывающее слабое освещение или мрачное настроение."}},"書く":{"b":"書く (かく)","p":"v","m":{"az":"yazmaq","en":"to write","ru":"писать"},"n":{"az":"「森」と書く = «Mori» yazmaq. 書いてある = yazılıb (yazılı durur).","en":"「森」と書く = write \"Mori\". 書いてある = is written.","ru":"「森」と書く = написать «Мори». 書いてある = написано."}},"服":{"b":"服 (ふく)","p":"n","m":{"az":"paltar","en":"clothes","ru":"одежда"}},"朝":{"b":"朝 (あさ)","p":"n","m":{"az":"səhər","en":"morning","ru":"утро"}},"木":{"b":"木 (き)","p":"n","m":{"az":"ağac; taxta","en":"tree; wood","ru":"дерево; древесина"}},"本":{"b":"本 (ほん)","p":"n","m":{"az":"kitab","en":"book","ru":"книга"}},"机":{"b":"机 (つくえ)","p":"n","m":{"az":"yazı masası","en":"desk","ru":"письменный стол"}},"来る":{"b":"来る (くる)","p":"v","m":{"az":"gəlmək","en":"to come","ru":"приходить"},"n":{"az":"Qeyri-müntəzəm feildir: 来ます (kimasu), 来た (kita), 来て (kite). 〜から来ました = ...-dan gəlmişəm. 迎えに来る = aparmağa gəlmək.","en":"Irregular verb: 来ます, 来た (kita), 来て (kite). 〜から来ました = I come from ...","ru":"Неправильный глагол: 来ます, 来た (kita), 来て (kite). 〜から来ました = я из ..."}},"森":{"b":"森 (もり)","p":"nm","m":{"az":"Mori (soyad; mənası 'meşə')","en":"Mori (surname; means 'forest')","ru":"Мори (фамилия; значит 'лес')"}},"次":{"b":"次 (つぎ)","p":"n","m":{"az":"növbəti; sonrakı","en":"next; following","ru":"следующий"},"n":{"az":"İsimdən əvvəl 次の, ardıcıllıq bildirmək üçün 次に işlənir.","en":"Use 次の before a noun and 次に to mean next in a sequence.","ru":"Перед существительным используется 次の, а для следующего шага 次に."}},"欲しい":{"b":"欲しい (ほしい)","p":"ai","m":{"az":"istəmək, arzulamaq","en":"to want, to desire","ru":"хотеть, желать"},"n":{"az":"い-sifətdir; istənilən əşya adətən が ilə işlənir: 水が欲しい.","en":"An i-adjective; the desired thing usually takes が: 水が欲しい.","ru":"Это i-прилагательное; желаемый предмет обычно отмечается が: 水が欲しい."}},"毎朝":{"b":"毎朝 (まいあさ)","p":"n","m":{"az":"hər səhər","en":"every morning","ru":"каждое утро"},"n":{"az":"Vaxt bildirəndə に işlənmir: 毎朝働きます.","en":"Takes no に as a time expression: 毎朝働きます.","ru":"При обозначении времени употребляется без に: 毎朝働きます."}},"泣く":{"b":"泣く (なく)","p":"v","m":{"az":"ağlamaq","en":"to cry","ru":"плакать"}},"泳ぐ":{"b":"泳ぐ (およぐ)","p":"v","m":{"az":"üzmək","en":"to swim","ru":"плавать"},"n":{"az":"泳ぎたくない - üzmək istəmirəm; 〜たい istək, 〜たくない isə inkar bildirir.","en":"泳ぎたくない means not wanting to swim; 〜たい expresses desire and 〜たくない negates it.","ru":"泳ぎたくない означает не хочу плавать; 〜たい выражает желание, а 〜たくない - отрицание."}},"海":{"b":"海 (うみ)","p":"n","m":{"az":"dəniz","en":"sea","ru":"море"}},"消える":{"b":"消える (きえる)","p":"v","m":{"az":"sönmək, yox olmaq","en":"to go out, disappear","ru":"гаснуть, исчезать"},"n":{"az":"消えそうになる = az qala sönmək.","en":"消えそうになる = be about to go out.","ru":"消えそうになる = вот-вот погаснуть."}},"渡す":{"b":"渡す (わたす)","p":"v","m":{"az":"vermək, uzatmaq","en":"hand over, pass","ru":"передавать"},"n":{"az":"Keçişli feldir: 人に物を渡す “kiməsə nəsə vermək”; 渡る isə “qarşı tərəfə keçmək” deməkdir.","en":"A transitive verb: 人に物を渡す means “hand something to someone”; 渡る means “cross.”","ru":"Переходный глагол: 人に物を渡す «передать кому-то что-то»; 渡る означает «пересекать, переходить»."}},"猫":{"b":"猫 (ねこ)","p":"n","m":{"az":"pişik","en":"cat","ru":"кошка"}},"猿":{"b":"猿 (さる)","p":"n","m":{"az":"meymun","en":"monkey","ru":"обезьяна"}},"現れる":{"b":"現れる (あらわれる)","p":"v","m":{"az":"görünmək; ortaya çıxmaq","en":"appear; emerge","ru":"появляться"},"n":{"az":"Təsirsiz feldir; 現す nəyisə üzə çıxarmaq və ya göstərmək deməkdir.","en":"An intransitive verb; 現す means to reveal or show something.","ru":"Непереходный глагол; 現す означает обнаружить или показать что-либо."}},"用意":{"b":"用意 (ようい)","p":"n","m":{"az":"hazırlıq, hazırlama","en":"preparation","ru":"подготовка"},"n":{"az":"用意します hazırlamaq, 用意ができました hazır olmaq deməkdir.","en":"用意します means to prepare, and 用意ができました means preparation is complete.","ru":"用意します означает подготовить, а 用意ができました - всё готово."}},"町":{"b":"町 (まち)","p":"n","m":{"az":"şəhərcik; məhəllə","en":"town; neighborhood","ru":"городок; квартал"}},"百個":{"b":"百個 (ひゃっこ)","p":"nu","m":{"az":"yüz ədəd","en":"one hundred items","ru":"сто штук"},"n":{"az":"個 ümumi əşya sayğacıdır; 百個 ひゃっこ oxunur.","en":"個 is a general item counter; 百個 is read ひゃっこ.","ru":"個 - общий счётчик предметов; 百個 читается ひゃっこ."}},"目":{"b":"目 (め)","p":"n","m":{"az":"göz","en":"eye","ru":"глаз"}},"秘密":{"b":"秘密 (ひみつ)","p":"n","m":{"az":"sirr","en":"secret","ru":"секрет; тайна"}},"空":{"b":"空 (そら)","p":"n","m":{"az":"göy, səma","en":"sky","ru":"небо"}},"窓":{"b":"窓 (まど)","p":"n","m":{"az":"pəncərə","en":"window","ru":"окно"}},"立つ":{"b":"立つ (たつ)","p":"v","m":{"az":"dayanmaq, ayağa qalxmaq","en":"to stand","ru":"стоять, вставать"}},"竜":{"b":"竜 (りゅう)","p":"n","m":{"az":"əjdaha","en":"dragon","ru":"дракон"}},"笑う":{"b":"笑う (わらう)","p":"v","m":{"az":"gülmək, gülümsəmək","en":"to laugh, to smile","ru":"смеяться, улыбаться"},"n":{"az":"笑うと = gülümsəyəndə (feil + と = 'edəndə').","en":"笑うと = when he smiled.","ru":"笑うと = когда он улыбался."}},"笑顔":{"b":"笑顔 (えがお)","p":"n","m":{"az":"təbəssüm, gülər üz","en":"smile, smiling face","ru":"улыбка, улыбающееся лицо"}},"箱":{"b":"箱 (はこ)","p":"n","m":{"az":"qutu","en":"box","ru":"коробка"}},"紙":{"b":"紙 (かみ)","p":"n","m":{"az":"kağız","en":"paper","ru":"бумага"}},"緑":{"b":"緑 (みどり)","p":"n","m":{"az":"yaşıl rəng, yaşıllıq","en":"green, greenery","ru":"зелёный цвет, зелень"},"n":{"az":"緑の服 = yaşıl paltar; 緑色 də yaşıl rəng deməkdir.","en":"緑の服 = green clothing; 緑色 also means the color green.","ru":"緑の服 = зелёная одежда; 緑色 также означает зелёный цвет."}},"置く":{"b":"置く (おく)","p":"v","m":{"az":"qoymaq","en":"to put, place","ru":"класть, ставить"}},"考える":{"b":"考える (かんがえる)","p":"v","m":{"az":"düşünmək, fikirləşmək, nəzərdən keçirmək","en":"to think, to consider","ru":"думать, обдумывать, рассматривать"},"n":{"az":"〜について考える - bir mövzu haqqında düşünmək.","en":"〜について考える means to think about a topic.","ru":"〜について考える означает думать о какой-либо теме."}},"聞く":{"b":"聞く (きく)","p":"v","m":{"az":"soruşmaq; eşitmək, qulaq asmaq","en":"to ask; to hear, listen","ru":"спрашивать; слушать"},"n":{"az":"Burada 'soruşmaq': 「…」と聞くと = «…» deyə soruşanda.","en":"Here 'ask': 「…」と聞くと = when she asked \"…\".","ru":"Здесь 'спросить': 「…」と聞くと = когда спросила «…»."}},"聞こえる":{"b":"聞こえる (きこえる)","p":"v","m":{"az":"eşidilmək","en":"to be audible; to hear","ru":"быть слышным; слышаться"},"n":{"az":"Səs が ilə göstərilir: 歌が聞こえる; bu, qəsdən qulaq asmaq deyil, səsin qulağa çatmasıdır.","en":"The sound takes が: 歌が聞こえる; it describes audibility rather than deliberate listening.","ru":"Звук обозначается через が: 歌が聞こえる; речь о слышимости, а не о намеренном слушании."}},"自分":{"b":"自分 (じぶん)","p":"n","m":{"az":"öz, özü","en":"oneself","ru":"сам, свой"},"n":{"az":"自分の名前 = öz adı.","en":"自分の名前 = one's own name.","ru":"自分の名前 = своё имя."}},"若い":{"b":"若い (わかい)","p":"ai","m":{"az":"gənc, cavan","en":"young","ru":"молодой"},"n":{"az":"İ-sifətidir: 若い人 “gənc insan”.","en":"An i-adjective: 若い人 means “a young person.”","ru":"Прилагательное на い: 若い人 «молодой человек»."}},"行く":{"b":"行く (いく)","p":"v","m":{"az":"getmək","en":"go","ru":"идти; ехать"},"n":{"az":"İstiqamət に və ya へ ilə göstərilir; て forması 行って, keçmiş forması 行った olur.","en":"The destination takes に or へ; its irregular forms are 行って and 行った.","ru":"Направление обозначается に или へ; особые формы: 行って и 行った."}},"袋":{"b":"袋 (ふくろ)","p":"n","m":{"az":"torba, paket","en":"bag, sack","ru":"пакет, мешок"}},"見る":{"b":"見る (みる)","p":"v","m":{"az":"baxmaq, görmək","en":"to see, to look","ru":"смотреть, видеть"},"n":{"az":"月を見てください = Aya baxın.","en":"月を見てください = please look at the moon.","ru":"月を見てください = смотрите на луну."}},"言う":{"b":"言う (いう)","p":"v","m":{"az":"demək","en":"to say","ru":"сказать, говорить"},"n":{"az":"「…」と言いました = «…» dedi. Oxunuşu 'iu' kimi səslənir.","en":"「…」と言いました = said \"…\". Pronounced 'yuu'.","ru":"「…」と言いました = сказал «…»."}},"言葉":{"b":"言葉 (ことば)","p":"n","m":{"az":"söz, dil, ifadə","en":"word, language, expression","ru":"слово, язык, выражение"},"n":{"az":"日本語の言葉 = yapon sözü; 優しい言葉 = mehriban sözlər.","en":"日本語の言葉 = Japanese word; 優しい言葉 = kind words.","ru":"日本語の言葉 = японское слово; 優しい言葉 = добрые слова."}},"話":{"b":"話 (はなし)","p":"n","m":{"az":"söhbət, hekayə","en":"conversation, story","ru":"разговор, история"}},"話す":{"b":"話す (はなす)","p":"v","m":{"az":"danışmaq; söhbət etmək","en":"to speak; to talk","ru":"говорить; разговаривать"},"n":{"az":"Dil を, həmsöhbət と ilə göstərilir: 日本語を話す, 友達と話す.","en":"A language takes を and a conversation partner takes と: 日本語を話す, 友達と話す.","ru":"Язык обозначается через を, собеседник через と: 日本語を話す, 友達と話す."}},"買う":{"b":"買う (かう)","p":"v","m":{"az":"almaq; satın almaq","en":"buy","ru":"покупать"},"n":{"az":"て forması 買って olur.","en":"Its て-form is 買って.","ru":"Форма на て: 買って."}},"貸す":{"b":"貸す (かす)","p":"v","m":{"az":"borc vermək, müvəqqəti istifadəyə vermək","en":"to lend","ru":"давать взаймы"},"n":{"az":"友達に本を貸す dosta kitab vermək deməkdir; qarşılığı 借りる borc götürməkdir.","en":"友達に本を貸す means to lend a book to a friend; 借りる means to borrow.","ru":"友達に本を貸す означает дать другу книгу; 借りる значит взять взаймы."}},"走る":{"b":"走る (はしる)","p":"v","m":{"az":"qaçmaq","en":"run","ru":"бежать"},"n":{"az":"る ilə bitsə də birinci qrup feldir; 走らせる qaçırmaq, 車を走らせる isə maşını sürmək deməkdir.","en":"Despite ending in る, it is a group 1 verb; 走らせる means make run, and 車を走らせる means drive a car.","ru":"Несмотря на る, это глагол первой группы; 走らせる означает заставить бежать, а 車を走らせる вести машину."}},"足":{"b":"足 (あし)","p":"n","m":{"az":"ayaq","en":"foot; leg","ru":"нога; ступня"},"n":{"az":"Kontekstdən asılı olaraq ayağın pəncəsini və ya bütün aşağı ətrafı bildirir.","en":"Can mean the foot or the whole leg, depending on context.","ru":"В зависимости от контекста обозначает ступню или всю ногу."}},"近く":{"b":"近く (ちかく)","p":"n","m":{"az":"yaxınlıq, yaxın yer","en":"vicinity, nearby place","ru":"окрестности, близкое место"},"n":{"az":"Nの近く “N-in yaxınlığı”, 近くに isə “yaxınlıqda” deməkdir.","en":"Nの近く means “near N,” and 近くに means “nearby.”","ru":"Nの近く означает «рядом с N», а 近くに означает «поблизости»."}},"遊ぶ":{"b":"遊ぶ (あそぶ)","p":"v","m":{"az":"oynamaq; əylənmək","en":"to play; to have fun","ru":"играть; развлекаться"},"n":{"az":"て-forması 遊んで-dir; 友達と遊ぶ = dostlarla oynamaq və ya vaxt keçirmək.","en":"Its て-form is 遊んで; 友達と遊ぶ means to play or spend time with friends.","ru":"て-форма: 遊んで; 友達と遊ぶ означает играть или проводить время с друзьями."}},"部屋":{"b":"部屋 (へや)","p":"n","m":{"az":"otaq","en":"room","ru":"комната"}},"金色":{"b":"金色 (きんいろ)","p":"n","m":{"az":"qızılı rəng","en":"gold color","ru":"золотой цвет"},"n":{"az":"金色に光る = qızılı rəngdə parlamaq.","en":"金色に光る = shine gold.","ru":"金色に光る = сиять золотом."}},"門":{"b":"門 (もん)","p":"n","m":{"az":"darvaza","en":"gate","ru":"ворота"}},"閉じる":{"b":"閉じる (とじる)","p":"v","m":{"az":"bağlamaq; bağlanmaq","en":"to close; to shut","ru":"закрывать; закрываться"},"n":{"az":"Həm təsirli, həm təsirsizdir: 本を閉じる = kitabı bağlamaq, 店が閉じる = mağazanın bağlanması.","en":"Can be transitive or intransitive: 本を閉じる = close a book, 店が閉じる = a shop closes.","ru":"Бывает переходным и непереходным: 本を閉じる = закрыть книгу, 店が閉じる = магазин закрывается."}},"閉める":{"b":"閉める (しめる)","p":"v","m":{"az":"bağlamaq (qapı, pəncərə)","en":"to close; to shut","ru":"закрывать"},"n":{"az":"他動詞: 閉める bağlamaq, 閉まる isə bağlanmaq deməkdir.","en":"Transitive verb: 閉める means to close something, while 閉まる means to close by itself.","ru":"Переходный глагол: 閉める - закрывать, 閉まる - закрываться."}},"開く":{"b":"開く (あく)","p":"v","m":{"az":"açılmaq","en":"open","ru":"открываться"},"n":{"az":"Qapı üçün あく oxunur və təsirsizdir, təsirli qarşılığı 開ける olur; 開く həmçinin ひらく oxuna bilər.","en":"For doors, it is read あく and is intransitive, paired with 開ける; 開く can also be read ひらく.","ru":"О дверях читается あく и является непереходным, с парой 開ける; 開く также может читаться ひらく."}},"開ける":{"b":"開ける (あける)","p":"v","m":{"az":"açmaq","en":"to open","ru":"открывать"},"n":{"az":"開けると = açanda.","en":"開けると = when he opened.","ru":"開けると = когда открыл."}},"降る":{"b":"降る (ふる)","p":"v","m":{"az":"yağmaq","en":"fall as rain or snow","ru":"идти о дожде или снеге"},"n":{"az":"Yağıntı が ilə göstərilir: 雨が降る, 雪が降る.","en":"Precipitation takes が: 雨が降る, 雪が降る.","ru":"Осадки оформляются が: 雨が降る, 雪が降る."}},"雨":{"b":"雨 (あめ)","p":"n","m":{"az":"yağış","en":"rain","ru":"дождь"}},"青い":{"b":"青い (あおい)","p":"ai","m":{"az":"mavi, göy","en":"blue","ru":"синий, голубой"}},"頭":{"b":"頭 (あたま)","p":"n","m":{"az":"baş","en":"head","ru":"голова"}},"頼む":{"b":"頼む (たのむ)","p":"v","m":{"az":"xahiş etmək; sifariş vermək","en":"to request; to order","ru":"просить; заказывать"},"n":{"az":"頼みました keçmiş nəzakətli formadır.","en":"頼みました is the polite past form.","ru":"頼みました - вежливая форма прошедшего времени."}},"風":{"b":"風 (かぜ)","p":"n","m":{"az":"külək","en":"wind","ru":"ветер"}},"飛ぶ":{"b":"飛ぶ (とぶ)","p":"v","m":{"az":"uçmaq, havada hərəkət etmək","en":"to fly","ru":"летать, лететь"},"n":{"az":"Təsirsiz feldir, 飛びました nəzakətli keçmiş formadır.","en":"An intransitive verb, with 飛びました as its polite past form.","ru":"Непереходный глагол, 飛びました - его вежливая прошедшая форма."}},"駅":{"b":"駅 (えき)","p":"n","m":{"az":"stansiya","en":"station","ru":"станция"}},"魔法":{"b":"魔法 (まほう)","p":"n","m":{"az":"sehr, sehrbazlıq","en":"magic, sorcery","ru":"магия, волшебство"},"n":{"az":"魔法を使う = sehr işlətmək.","en":"魔法を使う = to use magic or cast a spell.","ru":"魔法を使う = использовать магию или колдовать."}},"鳴く":{"b":"鳴く (なく)","p":"v","m":{"az":"heyvan səsi çıxarmaq; ötmək","en":"make an animal sound; chirp","ru":"издавать голос; петь о птицах"},"n":{"az":"Heyvan və quş səsləri üçün işlənir; insanın ağlaması eyni oxunuşlu 泣く ilə yazılır.","en":"Used for animal and bird cries; human crying is written 泣く with the same reading.","ru":"Употребляется для голосов животных и птиц; человеческий плач записывается 泣く с тем же чтением."}}}};